// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Hukuk, vatandaşlık, demokrasi, insan hakları ve Türkiye'nin anayasal düzeni (orta).
const ozSocialscience4Orta = <(String, String, List<String>, String)>[
  ('Bir kişi otobüste yaşlı birine yer vermediği için çevresindekilerin kınayıcı bakışlarıyla karşılaşıyor. Bu durumda işleyen yaptırım hangi kural türüne özgüdür?', 'Görgü ve ahlak kurallarının manevi yaptırımı', ['Ceza hukukunun hapis yaptırımı', 'İdare hukukunun para cezası', 'Borçlar hukukunun mahkemece hükmedilen tazminat yaptırımı'], 'Yer vermemek bir hukuk kuralını çiğnemek değildir; toplumun kınaması manevi bir yaptırımdır ve görgü ile ahlak kurallarına özgüdür.'),
  ('Ali, Ayşe\'ye kitabını 200 liraya satmıştır. Bu ilişkide Ali\'nin parayı isteme yetkisi ile Ayşe\'nin parayı ödeme yükümlülüğü sırasıyla hangi kavramlarla ifade edilir?', 'Hak ve borç', ['Borç ve hak', 'Ehliyet ve yaptırım', 'Kişilik ve sorumluluk'], 'Satıcının bedeli isteme yetkisi alacak hakkıdır; alıcının ödeme yükümlülüğü ise borçtur.'),
  ('Komşusunun camını kıran bir kişinin mahkeme kararıyla zararı ödemeye mahkûm edilmesi hangi yaptırımdır?', 'Tazminat', ['Hükümsüzlük', 'Disiplin cezası', 'Zorla yerine getirme'], 'Hukuka aykırı bir eylemle başkasına zarar veren kişinin bu zararı parayla gidermesi tazminat yaptırımıdır.'),
  ('Kanunun öngördüğü şekle uyulmadan yapılan bir hukuki işlemin baştan itibaren hüküm doğurmaması hangi yaptırımla açıklanır?', 'Kesin hükümsüzlük', ['Tazminat', 'Cebri icra yoluyla işlemin zorla yerine getirilmesi', 'Ceza'], 'Kesin hükümsüzlük (butlan), kanuna veya şekil şartına aykırı işlemin hiç doğmamış sayılmasıdır.'),
  ('Görevini ihmal eden bir memura kurumunca kınama cezası verilmesi hangi yaptırım türüne girer?', 'Disiplin cezası', ['Adli para cezası', 'Tazminat', 'Cebri icra'], 'Disiplin cezaları, kamu görevlilerinin görevle ilgili kurallara aykırı davranışlarına karşı idarece verilir; uyarma ve kınama bunlardandır.'),
  ('Normlar hiyerarşisi ilkesinin temel sonucu aşağıdakilerden hangisidir?', 'Alt düzeydeki norm üst düzeydeki norma aykırı olamaz.', ['Yeni çıkan her düzenleme anayasayı değiştirir.', 'Yönetmelikler kanunları yürürlükten kaldırabilir.', 'Mahkeme kararları kanunlardan üstündür.'], 'Hukuk düzeni basamaklı bir yapıdadır; her norm geçerliliğini üstündeki normdan alır ve ona uygun olmak zorundadır.'),
  ('Türk Medeni Kanunu\'nun 1. maddesine göre kanunda uygulanabilir bir hüküm, örf ve âdet hukuku kuralı da yoksa hâkim nasıl karar verir?', 'Kendisi kanun koyucu olsaydı koyacağı kurala göre', ['Davayı reddederek tarafları uzlaşmaya gönderir.', 'Yabancı ülke kanunlarını doğrudan uygular.', 'Dosyayı görüş alınması için TBMM Adalet Komisyonuna gönderir.'], 'TMK m.1\'e göre bu durumda hâkim, kanun koyucu olsaydı koyacağı kurala göre karar verir; bilimsel görüşler ve yargı kararları ona yol gösterir.'),
  ('Yargı kararları ve bilimsel görüşler hukukun kaynakları arasında nasıl sınıflandırılır?', 'Yardımcı (tali) kaynak', ['Asli yazılı kaynak', 'Asli yazısız kaynak', 'Uluslararası ve doğrudan bağlayıcı kaynak'], 'Bilimsel içtihat ve yargı kararları hâkime yol gösteren yardımcı kaynaklardır; asli kaynaklar ise yazılı hukuk ile örf ve âdettir.'),
  ('Aşağıdaki hukuk dallarından hangisi özel hukuk içinde yer alır?', 'Eşya hukuku', ['İdare hukuku', 'Vergi hukuku', 'Anayasa hukuku'], 'Eşya hukuku, kişilerin mallar üzerindeki haklarını eşitlik temelinde düzenler ve medeni hukukun bir parçası olarak özel hukuktadır.'),
  ('Bir şirketin ticaret siciline kaydı, ticari defterleri ve kıymetli evrakı hangi hukuk dalının konusudur?', 'Ticaret hukuku', ['Ceza hukuku', 'İdare hukuku', 'Anayasa hukuku ve idare hukuku'], 'Ticaret hukuku, tacirleri, ticari işletmeleri, şirketleri ve kıymetli evrakı düzenleyen özel hukuk dalıdır.'),
  ('Hak ehliyeti ile fiil ehliyeti arasındaki temel fark nedir?', 'Hak ehliyeti haklara sahip olabilmeyi, fiil ehliyeti kendi işlemleriyle hak edinip borç altına girebilmeyi ifade eder.', ['Hak ehliyeti yalnız yetişkinlere, fiil ehliyeti herkese tanınır.', 'Hak ehliyeti sözleşme yapma, fiil ehliyeti mirasçı olma gücüdür.', 'İkisi aynı kavramdır ve yalnız tüzel kişiler için kullanılır.'], 'Her insan hak ehliyetine sahiptir; fiil ehliyeti için ise ayırt etme gücü, erginlik ve kısıtlı olmama koşulları aranır.'),
  ('On altı yaşındaki bir genç, mahkeme kararıyla ergin kılınmıştır. Bu kararın onun için doğurduğu temel sonuç nedir?', 'Tam fiil ehliyeti kazanır.', ['Hak ehliyetini ilk kez kazanır.', 'Kişiliği bu kararla başlar.', 'Yalnız oy kullanma hakkı kazanır.'], 'TMK\'ya göre on beş yaşını dolduran küçük, kendi isteği ve ana-babasının rızasıyla mahkeme kararıyla ergin kılınabilir ve tam ehliyetli olur. Seçme hakkı ise anayasada ayrıca 18 yaşa bağlıdır.'),
  ('Bir evin tapuda kimin adına kayıtlı olduğu ve o eve ilişkin mülkiyet hakkı hangi hukuk alanında incelenir?', 'Eşya hukuku', ['Ceza hukuku', 'Aile hukuku', 'İş hukuku ve sosyal güvenlik hukuku'], 'Mülkiyet, sınırlı ayni haklar ve tapu sicili eşya hukukunun konularıdır.'),
  ('Sözleşmenin kurulması için tarafların hangi unsurda anlaşması gerekir?', 'Karşılıklı ve birbirine uygun irade beyanlarında', ['Yalnızca noterde imza atılmasında', 'Devletin önceden onay vermesinde', 'Tarafların aynı mesleği yapmasında ve aynı şehirde oturmasında'], 'Sözleşme, tarafların karşılıklı ve birbirine uygun irade açıklamalarıyla kurulur; kural olarak şekil şartı yoktur.'),
  ('Türk Medeni Kanunu\'na göre evlenmede hangi evlilik biçimi esas alınmıştır?', 'Resmî memur önünde yapılan medeni nikâh', ['Dinî nikâh', 'Aile meclisi kararıyla evlilik', 'Ailelerin sözlü anlaşmasıyla kurulan evlilik'], 'Türk hukukunda evlilik, yetkili evlendirme memuru önünde yapılan resmî törenle kurulur ve tek eşlilik esastır.'),
  ('Roma\'da halkın bilgisine sunulmak üzere tunç levhalara yazılan ve Roma hukukunun ilk yazılı derlemesi sayılan kanunlar hangisidir?', 'On İki Levha Kanunları', ['Corpus Juris Civilis', 'Magna Carta', 'Mecelle-i Ahkâm-ı Adliye'], 'MÖ 5. yüzyılda hazırlanan On İki Levha Kanunları, Roma özel hukukunun ilk yazılı temelidir.'),
  ('Bizans İmparatoru Justinianus döneminde yapılan Roma hukuku derlemesinin bugünkü Kıta Avrupası hukuk sistemleri için önemi nedir?', 'Modern medeni kanunlara kaynaklık etmiştir.', ['İlk kez kuvvetler ayrılığını getirmiştir.', 'Genel oy ilkesini ilk kez tanımıştır.', 'Anayasa yargısını ve bireysel başvuru yolunu kurmuştur.'], 'Corpus Juris Civilis, Orta Çağ\'da yeniden keşfedilerek Fransız ve Alman medeni kanunları gibi Kıta Avrupası düzenlemelerinin temeli olmuştur.'),
  ('Osmanlı Devleti\'nde Tanzimat sonrasında Ahmet Cevdet Paşa başkanlığında hazırlanan ve borçlar hukukuna ilişkin kuralları içeren derleme hangisidir?', 'Mecelle', ['Kanun-i Esasi', 'Sened-i İttifak', 'Islahat Fermanı'], 'Mecelle-i Ahkâm-ı Adliye, 1869-1876 yılları arasında hazırlanmış, İslam hukukunun borçlar ve yargılama kurallarını madde madde derlemiştir.'),
  ('1926 tarihli Türk Ceza Kanunu hangi ülkenin ceza kanunundan uyarlanmıştır?', 'İtalya', ['İsviçre', 'Fransa', 'İngiltere'], '1926 Türk Ceza Kanunu, İtalyan Zanardelli Ceza Kanunu örnek alınarak hazırlanmıştır.'),
  ('Cumhuriyetin ilk yıllarında Avrupa ülkelerinden kanunların iktibas edilmesinin temel amacı neydi?', 'Hukukta birliği sağlayıp laik ve çağdaş bir hukuk düzeni kurmak', ['Osmanlı\'nın ödediği dış borçları silmek', 'Yalnızca ticaret anlaşmalarını kolaylaştırmak', 'Yargıyı yürütmeye bağlamak'], 'Farklı topluluklara farklı hukuk uygulanan dağınık yapı bırakılarak herkese eşit uygulanan laik bir hukuk düzeni hedeflenmiştir.'),
  ('2001 yılında kabul edilip 2002\'de yürürlüğe giren yeni Türk Medeni Kanunu ile eşler arasındaki mal rejimine ilişkin yasal rejim olarak hangisi benimsenmiştir?', 'Edinilmiş mallara katılma', ['Mal ayrılığı', 'Mal ortaklığı', 'Paylaşmalı mal ayrılığı rejimi'], '4721 sayılı TMK ile yasal mal rejimi mal ayrılığından edinilmiş mallara katılma rejimine dönüştürülmüştür.'),
  ('Ayırt etme gücüne sahip olmayan bir kişinin yaptığı hukuki işlemlerin genel sonucu nedir?', 'Kural olarak hüküm doğurmaz.', ['Her durumda geçerli sayılır.', 'Noter onayıyla kendiliğinden geçerlik kazanır.', 'Yalnız ceza hukukunda sonuç doğurur.'], 'TMK\'ya göre ayırt etme gücü bulunmayan kişinin fiilleri, kanunda gösterilen istisnalar dışında hukuki sonuç doğurmaz.'),
  ('Bir eylem işlendiği tarihte suç değildi; iki yıl sonra çıkan kanunla suç sayıldı. Bu eylemi yapan kişi yeni kanunla cezalandırılabilir mi?', 'Hayır, ceza kanunları failin aleyhine geriye yürümez.', ['Evet, yeni kanun her zaman geçmişe uygulanır.', 'Evet, ancak cezası yarıya indirilir.', 'Hayır, ama kişi tazminatla cezalandırılır.'], 'Anayasa m.38\'e göre kimse işlendiği zaman kanunun suç saymadığı bir fiilden dolayı cezalandırılamaz.'),
  ('Yargılanan bir sanık, avukatı aracılığıyla kendi aleyhine tanıklık etmeye zorlanamayacağını belirtiyor. Sanık hangi hakka dayanmaktadır?', 'Kendini ve yakınlarını suçlama yasağı', ['Bilgi edinme hakkı', 'Dilekçe hakkı', 'Mülkiyet hakkı ve miras hakkı'], 'Anayasa m.38\'e göre kimse kendisini ve kanunda gösterilen yakınlarını suçlayan bir beyanda bulunmaya veya delil göstermeye zorlanamaz.'),
  ('Bir suç için işlendikten sonra cezası hafifleten yeni bir kanun çıkarsa, henüz kesinleşmemiş davada hangi kanun uygulanır?', 'Fail lehine olan kanun', ['Her zaman eski kanun', 'Her zaman en ağır cezayı öngören kanun', 'Hâkimin seçeceği herhangi bir kanun'], 'Ceza hukukunda geriye yürüme yasağı fail aleyhinedir; lehe kanun geçmişe uygulanır.'),
  ('Anayasa\'ya göre kimsenin kanunen tabi olduğu mahkemeden başka bir merci önüne çıkarılamaması hangi ilkeyle ifade edilir?', 'Tabii hâkim güvencesi', ['Yargının aleniyeti', 'Kanunların geriye yürümezliği', 'Masumiyet karinesi'], 'Anayasa m.37, olağanüstü yetkili mahkeme kurulamayacağını ve kişinin önceden belirlenmiş mahkemede yargılanacağını öngörür.'),
  ('Mahkemelerde duruşmaların kural olarak herkese açık yapılmasının temel amacı nedir?', 'Yargının kamu denetimine açık olmasını sağlamak', ['Davaların süresini uzatmak', 'Tanıkların ifade vermesini engellemek', 'Hâkimin karar verme yetkisini salondaki dinleyicilere devretmek'], 'Aleniyet ilkesi (Anayasa m.141), yargılamanın şeffaflığını ve güvenilirliğini sağlar; genel ahlak veya kamu güvenliği gerekirse kapalı duruşma yapılabilir.'),
  ('Bir davada mahkeme, karşı tarafın sunduğu belgeleri sanığa göstermeden ve onu dinlemeden karar vermiştir. Bu durumda hangi hak ihlal edilmiştir?', 'Hukuki dinlenilme ve savunma hakkı', ['Seçme hakkı', 'Çalışma hakkı', 'Sağlık hakkı ve sosyal güvenlik hakkı'], 'Adil yargılanmanın gereği olarak taraflar iddia ve delillerden haberdar edilmeli, kendilerini savunma fırsatı bulmalıdır.'),
  ('Anayasa\'da "Herkes, meşru vasıta ve yollardan faydalanmak suretiyle yargı mercileri önünde davacı veya davalı olarak iddia ve savunma ile adil yargılanma hakkına sahiptir." hükmü hangi hakkı düzenler?', 'Hak arama hürriyeti', ['Dilekçe hakkı', 'Kamu hizmetine girme hakkı', 'Sendika kurma hakkı'], 'Anayasa m.36 hak arama hürriyetini düzenler; adil yargılanma ifadesi 2001 değişikliğiyle eklenmiştir.'),
  ('Bir davanın adli yargıya mı yoksa idari yargıya mı ait olduğu konusunda çıkan görev uyuşmazlıklarını kesin olarak çözen mahkeme hangisidir?', 'Uyuşmazlık Mahkemesi', ['Anayasa Mahkemesi', 'Yargıtay Büyük Genel Kurulu', 'Danıştay Dava Daireleri Kurulu'], 'Anayasa m.158\'e göre Uyuşmazlık Mahkemesi, adli ve idari yargı mercileri arasındaki görev ve hüküm uyuşmazlıklarını kesin olarak çözer.'),
  ('Bir vatandaş, belediyenin kendisine verdiği imar para cezasının hukuka aykırı olduğunu düşünüyor. Bu işlemin iptali için kural olarak hangi mahkemeye başvurmalıdır?', 'İdare mahkemesi', ['Asliye ceza mahkemesi', 'Aile mahkemesi', 'Asliye ticaret mahkemesi'], 'İdarenin tek taraflı işlemlerine karşı açılan iptal davaları idari yargının, ilk derecede idare mahkemelerinin görev alanındadır.'),
  ('İki tacir arasında ödenmemiş bir senet yüzünden çıkan uyuşmazlık genellikle hangi mahkemede görülür?', 'Asliye ticaret mahkemesi', ['İdare mahkemesi', 'Vergi mahkemesi', 'Anayasa Mahkemesi Genel Kurulu'], 'Ticari davalar, adli yargı içinde yer alan asliye ticaret mahkemelerinde görülür.'),
  ('Aşağıdakilerden hangisi hukuk devleti ilkesiyle çelişir?', 'İdarenin bazı işlemlerini yargı denetimi dışında tutan kanun', ['Bağımsız mahkemelerin varlığı', 'Temel hakların anayasal güvence altına alınması', 'Kanunların anayasaya uygunluğunun denetlenmesi'], 'Anayasa m.125\'e göre idarenin her türlü eylem ve işlemine karşı yargı yolu açıktır; istisnalar ancak anayasada sayılanlarla sınırlıdır.'),
  ('Anayasa\'ya göre idarenin eylem ve işlemlerinden doğan zararları ödemesi zorunluluğu, hukuk devletinin hangi unsurunu yansıtır?', 'İdarenin mali sorumluluğu', ['Yasama sorumsuzluğu', 'Cumhurbaşkanının cezai sorumsuzluğu', 'Kamu görevlilerinin dokunulmazlığı'], 'Anayasa m.125\'e göre idare, kendi eylem ve işlemlerinden doğan zararı ödemekle yükümlüdür.'),
  ('Temsilî bir sistemde, halkın bazı önemli konularda referandum ve halk girişimi gibi araçlarla doğrudan karar vermesine olanak tanınıyorsa bu sistem nasıl adlandırılır?', 'Yarı doğrudan demokrasi', ['Doğrudan demokrasi', 'Oligarşi', 'Meşruti monarşi ve mutlakiyet'], 'Yarı doğrudan demokrasi, temsil esasını halk oylaması, halk girişimi ve halk vetosu gibi araçlarla birleştirir.'),
  ('"Çoğunluğun yönetimi, azınlığın haklarına saygı" ilkesi neyi önlemeye yöneliktir?', 'Çoğunluğun baskısını', ['Seçimlerin düzenli yapılmasını', 'Siyasi partilerin kurulmasını', 'Basının haber yapmasını'], 'Demokrasi yalnızca sayısal çoğunluk değildir; çoğunluk azınlıkta kalanların temel haklarını ortadan kaldıramaz.'),
  ('Demokrasilerde yöneticilerin belirli aralıklarla seçimle yenilenmesinin temel işlevi nedir?', 'Halkın yöneticileri değiştirebilmesine imkân vermek', ['Yöneticilerin ömür boyu görevde kalmasını sağlamak', 'Siyasi partilerin sayısını azaltmak', 'Yargının denetim yetkisini kaldırmak'], 'Düzenli ve serbest seçimler iktidarın barışçıl yollarla değişmesini sağlar.'),
  ('Abraham Lincoln\'ün Gettysburg Konuşması\'nda geçen ve demokrasinin tanımı olarak sık kullanılan ifade hangisidir?', 'Halkın, halk tarafından, halk için yönetimi', ['Kanunların ruhu kuvvetler ayrılığıdır', 'İnsan insanın kurdudur', 'Devlet benim ve benden sonra tufan'], 'Lincoln 1863\'teki konuşmasında demokrasiyi halkın, halk tarafından ve halk için yönetimi olarak dile getirmiştir.'),
  ('Bir bakanlık, mahkemenin kesinleşmiş kararını yerine getirmeyeceğini açıklamıştır. Bu tutum, Anayasa\'nın hangi kuralına aykırıdır?', 'Yasama, yürütme ve idare mahkeme kararlarına uymak zorundadır.', ['Milletvekilleri yasama dokunulmazlığına sahiptir.', 'Vergi ödevi herkese aittir.', 'Seçimler serbest ve eşit oyla yapılır.'], 'Anayasa m.138\'e göre yasama ve yürütme organları ile idare mahkeme kararlarına uymak zorundadır; bu organlar kararları değiştiremez ve yerine getirilmesini geciktiremez.'),
  ('1946 seçimleri "açık oy, gizli tasnif" yöntemiyle yapılmıştır. Bu uygulamada hangi demokratik seçim ilkesi ihlal edilmiştir?', 'Gizli oy', ['Genel oy', 'Tek derece', 'Eşit oy'], '1946\'da oylar herkesin önünde kullanılıp sayımı kapalı yapıldığı için oy gizliliği sağlanmamıştı; 1950 seçimleri gizli oy, açık sayım ilkesiyle yapıldı.'),
  ('Türkiye\'de 1950 genel seçimlerinde kabul edilen ve bugün de geçerli olan oy kullanma ve sayım ilkesi hangisidir?', 'Gizli oy, açık sayım ve döküm', ['Açık oy, gizli sayım', 'Açık oy, açık sayım', 'Gizli oy, gizli sayım ve kapalı döküm'], '1950 seçimleri, yargı denetimi altında gizli oy ve açık sayım-döküm ilkesiyle yapılmış ve iktidar barışçıl biçimde değişmiştir.'),
  ('Nispi temsil sisteminin çoğunluk sistemine göre en belirgin üstünlüğü hangisidir?', 'Partilerin meclise aldıkları oy oranında yakın girmesi', ['Tek parti iktidarını kesin olarak garanti etmesi', 'Seçimlerin daha az sıklıkla yapılmasını sağlaması', 'Seçmen sayısını azaltması'], 'Nispi temsil, parlamentonun toplumdaki görüş dağılımını daha adil yansıtmasını sağlar; ancak koalisyon olasılığını artırabilir.'),
  ('D\'Hondt yönteminde 3 sandalyeli bir çevrede A partisi 9.000, B partisi 6.000, C partisi 2.000 oy almıştır. Sandalyeler nasıl dağılır?', 'A: 2, B: 1, C: 0', ['A: 1, B: 1, C: 1', 'A: 3, B: 0, C: 0', 'A: 1, B: 2, C: 0'], 'Bölümler: A 9000, 4500, 3000; B 6000, 3000; C 2000. En büyük üç değer A 9000, B 6000 ve A 4500 olduğundan A iki, B bir sandalye alır.'),
  ('Seçimin ilk turunda hiçbir aday geçerli oyların salt çoğunluğunu alamazsa ilk iki adayın yarıştığı ikinci bir tur yapılır. Bu yöntem hangisidir?', 'İki turlu çoğunluk sistemi', ['D\'Hondt sistemi', 'Basit çoğunluk sistemi', 'Tek liste usulüyle yapılan nispi temsil sistemi'], 'İki turlu sistemde ilk turda salt çoğunluk aranır; sağlanamazsa en çok oy alan iki aday ikinci turda yarışır. Türkiye\'de Cumhurbaşkanı seçimi bu yöntemle yapılır.'),
  ('Türkiye\'de Cumhurbaşkanı seçiminde ilk oylamada adayın seçilebilmesi için hangi çoğunluk gerekir?', 'Geçerli oyların salt çoğunluğu', ['Kayıtlı seçmenlerin üçte ikisi', 'Geçerli oyların üçte biri', 'Oyların en az yüzde yetmiş beşi ve ek olarak katılım şartı'], 'Anayasa m.101\'e göre geçerli oyların salt çoğunluğunu alan aday seçilir; alınamazsa ilk iki aday arasında ikinci oylama yapılır.'),
  ('Parlamenter sistemde yürütmenin iki başlı olması ne anlama gelir?', 'Devlet başkanı ile bakanlar kurulunun ayrı olması', ['İki ayrı meclisin bulunması', 'Ülkenin iki başkentinin olması', 'İki başbakanın aynı anda görev yapması ve sırayla imza atması'], 'Parlamenter sistemde sembolik yetkili ve sorumsuz devlet başkanının yanında, siyasi sorumluluğu taşıyan başbakan ve bakanlar kurulu bulunur.'),
  ('Hükümetin meclisin güvenine dayanması ve güvensizlik oyuyla düşürülebilmesi hangi hükümet sisteminin ayırt edici özelliğidir?', 'Parlamenter sistem', ['Başkanlık sistemi', 'Mutlak monarşi', 'Meclis hükümeti sisteminin İsviçre dışındaki uygulaması'], 'Parlamenter sistemde hükümet meclise karşı siyasi olarak sorumludur; buna karşılık yürütme de belli koşullarda meclisi feshedebilir.'),
  ('Yasama ve yürütme yetkilerinin mecliste toplandığı, yürütme görevinin meclisin seçtiği bir kurulca yerine getirildiği sisteme ne ad verilir?', 'Meclis hükümeti sistemi', ['Başkanlık sistemi', 'Yarı başkanlık sistemi', 'Parlamenter monarşi ve kabine sistemi'], 'Meclis hükümeti sisteminde güçler birliği esastır; yürütme meclisin bir uzantısı gibidir. 1921 Teşkilat-ı Esasiye bu sistemi benimsemişti.'),
  ('Halkın seçtiği güçlü bir cumhurbaşkanının yanında meclise karşı sorumlu bir başbakanın bulunduğu, Fransa Beşinci Cumhuriyeti\'nde görülen sistem hangisidir?', 'Yarı başkanlık sistemi', ['Saf başkanlık sistemi', 'Meclis hükümeti sistemi', 'Mutlak monarşi'], '1958 Anayasası\'yla kurulan Fransız sistemi, başkanlık ve parlamenter sistem özelliklerini birleştiren yarı başkanlık sisteminin örneğidir.'),
  ('"Toplum Sözleşmesi" adlı eserinde genel irade kavramını ortaya koyan düşünür kimdir?', 'Jean-Jacques Rousseau', ['John Locke', 'Montesquieu', 'Thomas Hobbes ve Hugo Grotius'], 'Rousseau 1762\'de yayımlanan eserinde egemenliğin halkın genel iradesine dayandığını savunmuştur.'),
  ('Türkiye\'de kanun yapma yetkisinin TBMM\'ye, uyuşmazlıkları çözme yetkisinin bağımsız mahkemelere verilmesi hangi ilkenin uygulamasıdır?', 'Kuvvetler ayrılığı', ['Kuvvetler birliği', 'Yetki genişliği', 'Hiyerarşik denetim ve idari vesayet'], 'Anayasa\'nın başlangıç kısmı ve m.7, 8, 9 yasama, yürütme ve yargı yetkilerini ayrı organlara verir.'),
  ('Federal devleti üniter devletten ayıran temel özellik hangisidir?', 'Federe birimlerin kendi anayasa ve yasama organlarına sahip olması', ['Başkentin bulunması', 'Bir bayrağının olması', 'Devletin uluslararası alanda diğer devletlerce tanınmış olması'], 'Federal devlette yasama ve yürütme yetkisi merkez ile federe devletler arasında anayasal olarak paylaşılır; ABD ve Almanya örnektir.'),
  ('Baskı gruplarını siyasi partilerden ayıran temel özellik hangisidir?', 'İktidar olmayı değil, karar alıcıları etkilemeyi amaçlamaları', ['Seçimlere aday göstermeleri', 'Hükümet kurma hedefi taşımaları', 'Meclise kendi adlarıyla milletvekili sokmaları'], 'Sendikalar, işveren örgütleri ve meslek kuruluşları gibi baskı grupları belirli çıkarları savunmak için yönetimi etkiler, ancak iktidara talip olmaz.'),
  ('Bir mahallede yaşayanların parkın korunması için bir dernek kurup imza toplaması ve belediyeye başvurması hangi kavrama örnektir?', 'Sivil toplum örgütlenmesi', ['Yasama faaliyeti', 'Yargı denetimi', 'Kamu görevine giriş ve kadro tahsisi'], 'Sivil toplum, devletten bağımsız olarak gönüllülük esasıyla örgütlenen ve kamusal konularda etkinlik gösteren yapıları kapsar.'),
  ('Anayasa\'ya göre siyasi partilerin kapatılmasına hangi mahkeme karar verir?', 'Anayasa Mahkemesi', ['Yargıtay', 'Danıştay', 'Ankara Asliye Ceza Mahkemesi'], 'Anayasa m.69\'a göre siyasi partilerin kapatılması davası Yargıtay Cumhuriyet Başsavcılığınca açılır ve Anayasa Mahkemesince karara bağlanır.'),
  ('Türkiye\'de çok partili hayata geçişte 1946 yılında kurulan ve 1950\'de iktidara gelen parti hangisidir?', 'Demokrat Parti', ['Serbest Cumhuriyet Fırkası', 'Terakkiperver Cumhuriyet Fırkası', 'Millî Kalkınma Partisi'], 'Celal Bayar, Adnan Menderes, Refik Koraltan ve Fuat Köprülü\'nün kurduğu Demokrat Parti 1950 seçimlerini kazanmıştır.'),
  ('Bir kişinin, para karşılığında bile olsa özgürlüğünü başkasına devredip köle olmayı kabul eden sözleşmesi hukuken geçersizdir. Bu durum insan haklarının hangi niteliğiyle açıklanır?', 'Devredilemezlik', ['Evrensellik', 'Bölünmezlik', 'Sınırlanabilirlik'], 'İnsan hakları devredilemez ve vazgeçilemez; kişi kendi rızasıyla bile bu haklardan tamamen vazgeçemez.'),
  ('Bir hakkın "dokunulmaz" olması devlet için hangi yükümlülüğü doğurur?', 'O hakkı ihlal etmeme ve başkalarının ihlaline karşı koruma', ['O hakkı istediği zaman kaldırabilme', 'O hakkı yalnız seçim dönemlerinde tanıma', 'O hakkın kullanımını vergiye bağlama'], 'Dokunulmazlık, devletin hakkın özüne müdahale edemeyeceğini ve hakkı koruma ödevini ifade eder.'),
  ('Şanlı Devrim\'in ardından 1689\'da kabul edilen ve parlamentonun krala karşı üstünlüğünü pekiştiren İngiliz belgesi hangisidir?', 'Haklar Bildirgesi', ['Magna Carta', 'Habeas Corpus', 'İnsan ve Yurttaş Hakları Bildirgesi'], '1689 Bill of Rights ile kralın parlamento onayı olmadan vergi koyması ve kanunları askıya alması yasaklanmıştır.'),
  ('1776\'da yayımlanan ve "bütün insanların eşit yaratıldığı" ilkesine dayanarak yaşam, özgürlük ve mutluluğu arama haklarını vurgulayan belge hangisidir?', 'Amerikan Bağımsızlık Bildirgesi', ['Fransız İnsan ve Yurttaş Hakları Bildirgesi', 'İngiliz Haklar Bildirgesi', 'Magna Carta'], 'Thomas Jefferson\'ın kaleme aldığı Bağımsızlık Bildirgesi, 4 Temmuz 1776\'da kabul edilmiştir.'),
  ('Temiz bir çevrede yaşama hakkı ve barış hakkı, yalnız tek bir devletin çabasıyla değil uluslararası işbirliğiyle sağlanabilir. Bu haklar hangi gruptadır?', 'Üçüncü kuşak dayanışma hakları', ['Birinci kuşak kişisel haklar', 'İkinci kuşak sosyal haklar', 'Siyasal katılım hakları'], 'Üçüncü kuşak haklar 20. yüzyılın ikinci yarısında gündeme gelmiş, kolektif nitelikli dayanışma haklarıdır.'),
  ('Kişinin devlete karşı korunan özel alanını ve devletin bu alana giremeyeceğini ifade eden haklara ne ad verilir?', 'Negatif statü hakları', ['Pozitif statü hakları', 'Aktif statü hakları', 'Siyasal katılım hakları ve ödevleri'], 'Negatif statü hakları (koruyucu haklar), kişi dokunulmazlığı, konut dokunulmazlığı ve haberleşme özgürlüğü gibi devletin müdahalesini sınırlayan haklardır.'),
  ('Seçme, seçilme, siyasi parti kurma ve dilekçe hakkı hangi statü hakları grubundadır?', 'Aktif statü hakları', ['Negatif statü hakları', 'Pozitif statü hakları', 'Koruyucu haklar grubu'], 'Aktif statü hakları bireyin devlet yönetimine katılmasını sağlayan siyasal haklardır.'),
  ('Aşağıdaki haklardan hangisi kişinin devlet yönetimine katılmasıyla ilgili değil, devletten hizmet istemesiyle ilgilidir?', 'Eğitim hakkı', ['Seçme hakkı', 'Siyasi parti üyeliği', 'Halk oylamasına katılma hakkı ve yükümlülüğü'], 'Eğitim hakkı pozitif statü hakkıdır; diğer seçenekler aktif statüdeki siyasal haklardır.'),
  ('1982 Anayasası\'nın "Temel Haklar ve Ödevler" kısmında "Sosyal ve Ekonomik Haklar ve Ödevler" bölümü hangi bölümden hemen sonra gelir?', 'Kişinin Hakları ve Ödevleri', ['Siyasi Haklar ve Ödevler', 'Genel Esaslar', 'Yasama'], 'İkinci kısım sırasıyla Genel Hükümler, Kişinin Hakları ve Ödevleri, Sosyal ve Ekonomik Haklar ve Ödevler ile Siyasi Haklar ve Ödevler bölümlerinden oluşur.'),
  ('Anayasa m.13\'e göre bir hakkı sınırlayan kanun, o hakkı kullanılamaz hâle getirecek kadar ağır kısıtlamalar getiremez. Bu güvenceye ne ad verilir?', 'Hakkın özüne dokunma yasağı', ['Kanunların geriye yürümezliği', 'Yasama sorumsuzluğu', 'Masumiyet karinesi'], 'Sınırlama hakkın çekirdeğini ortadan kaldırmamalıdır; özüne dokunulmuş bir hak artık kullanılamaz hâle gelir.'),
  ('Bir kanun, gürültüyü önlemek amacıyla bütün açık hava konserlerini süresiz yasaklamaktadır. Daha hafif bir önlemle aynı amaca ulaşılabileceği düşünülürse bu kanun hangi ilke açısından sorunludur?', 'Ölçülülük ilkesi', ['Laiklik ilkesi', 'Yerinden yönetim ilkesi', 'Kanunilik ilkesi ve suçta şahsilik'], 'Ölçülülük; sınırlamanın amaca elverişli, gerekli ve orantılı olmasını ister. Daha hafif bir yolla amaç sağlanabiliyorsa ağır yasak ölçüsüzdür.'),
  ('Anayasa m.15\'e göre savaş, seferberlik veya olağanüstü hallerde bile dokunulamayacak haklar arasında hangisi yer alır?', 'Kimsenin din ve vicdanını açıklamaya zorlanamaması', ['Toplantı ve gösteri yürüyüşü hakkı', 'Seyahat özgürlüğü', 'Basın özgürlüğü'], 'Çekirdek haklar arasında savaş hukukuna uygun fiiller dışında yaşam hakkı, maddi ve manevi bütünlük, din ve vicdanı açıklamaya zorlanmama, suç ve cezaların geriye yürümezliği ve masumiyet karinesi vardır.'),
  ('Anayasa\'da olağanüstü dönemlerde temel hakların kullanılmasının durdurulabilmesine ilişkin düzenlemenin bulunmasının amacı nedir?', 'Devletin varlığını tehdit eden durumlarda geçici ve ölçülü tedbir almak', ['Seçimleri süresiz olarak ertelemek', 'Bütün hakları kalıcı olarak kaldırmak', 'Yargı denetimini tamamen sonlandırmak'], 'Olağanüstü hal rejimi istisnaidir; alınan tedbirler durumun gerektirdiği ölçüde olmalı ve uluslararası hukuk yükümlülükleri ihlal edilmemelidir.'),
  ('Avrupa İnsan Hakları Mahkemesine bireysel başvuru yapılabilmesi için kural olarak önce hangi koşulun sağlanması gerekir?', 'İç hukuk yollarının tüketilmesi', ['Başvurucunun Avrupa Birliği vatandaşı olması', 'Avukatlık sınavının geçilmesi', 'Başvurunun bir devlet tarafından onaylanması ve imzalanması'], 'AİHS\'ye göre başvurucu önce ulusal yargı yollarını tüketmeli, ardından kesin karardan sonraki süre içinde mahkemeye başvurmalıdır.'),
  ('Türkiye, Avrupa İnsan Hakları Komisyonuna bireysel başvuru hakkını hangi yıl tanımıştır?', '1987', ['1950', '1961', '2004 yılı Anayasa değişikliğiyle'], 'Türkiye 1987\'de bireysel başvuru hakkını, 1990\'da ise Avrupa İnsan Hakları Mahkemesinin zorunlu yargı yetkisini tanımıştır.'),
  ('Uluslararası Ceza Mahkemesi ile Avrupa İnsan Hakları Mahkemesi arasındaki temel fark nedir?', 'Biri bireyleri suçlardan yargılar, diğeri devletlerin sözleşmeyi ihlal edip etmediğini inceler.', ['İkisi de yalnız devletler arasındaki sınır uyuşmazlıklarına bakar.', 'AİHM bireyleri hapis cezasına çarptırır, UCM ise devletleri denetler.', 'Her iki mahkeme de Birleşmiş Milletler Güvenlik Konseyine bağlı birer daire olarak çalışır.'], 'UCM soykırım ve savaş suçları gibi suçlarda kişilerin cezai sorumluluğunu inceler; AİHM ise taraf devletlere karşı yapılan başvurularda ihlal tespit eder.'),
  ('Bir mahkeme, boşanan ana-babadan hangisinin velayeti alacağına karar verirken öncelikle neyi gözetmelidir?', 'Çocuğun üstün yararını', ['Hangi ebeveynin daha zengin olduğunu', 'Hangi ebeveynin davayı önce açtığını', 'Akrabaların çoğunluğunun hangi ebeveyni ve hangi şehri desteklediğini'], 'Çocuk Haklarına Dair Sözleşme\'nin temel ilkelerinden biri, çocuklarla ilgili bütün kararlarda çocuğun yüksek yararının gözetilmesidir.'),
  ('Çocuk Haklarına Dair Sözleşme\'ye göre çocuğun, kendisini ilgilendiren konularda görüşünü özgürce ifade edebilmesi ve bu görüşe önem verilmesi hangi ilkeyle ilgilidir?', 'Katılım hakkı', ['Ayrımcılık yapmama', 'Yaşama ve gelişme hakkı', 'Koruma hakkı ve çalıştırılmama'], 'Katılım ilkesi, çocuğun yaşı ve olgunluğuna göre görüşlerinin dikkate alınmasını öngörür.'),
  ('Türkiye\'de kadınlar seçme ve seçilme hakkını ilk olarak hangi seçimlerde kullanabilmiştir?', 'Belediye seçimleri', ['Milletvekili seçimleri', 'Cumhurbaşkanı seçimi', 'Senato seçimleri ve kısmi seçimler'], '1930 tarihli Belediye Kanunu ile kadınlara belediye seçimlerinde seçme ve seçilme hakkı tanındı; 1933\'te muhtarlık seçimleri izledi.'),
  ('Birleşmiş Milletler\'in 1979\'da kabul ettiği CEDAW sözleşmesinin konusu nedir?', 'Kadınlara karşı her türlü ayrımcılığın önlenmesi', ['Çocuk işçiliğinin önlenmesi', 'Mültecilerin statüsünün belirlenmesi', 'Silahsızlanma ve nükleer silahların yayılmasının önlenmesi'], 'Kadınlara Karşı Her Türlü Ayrımcılığın Önlenmesi Sözleşmesi, siyasal, ekonomik ve toplumsal alanlarda kadın-erkek eşitliğini amaçlar.'),
  ('Bir işyerinde aynı işi yapan kadın ve erkek çalışana yalnızca cinsiyetleri nedeniyle farklı ücret ödenmektedir. Bu uygulama hangi ilkeye aykırıdır?', 'Ayrımcılık yasağı', ['Yasama sorumsuzluğu', 'Kanunların geriye yürümezliği', 'Yerinden yönetim ve idari vesayet'], 'Anayasa m.10 dil, ırk, renk, cinsiyet ve benzeri sebeplerle ayrım yapılmasını yasaklar; m.55 de adil ücreti düzenler.'),
  ('1982 Anayasası\'na göre basın hürdür ve sansür edilemez. Bu kural Anayasa\'nın hangi maddesinde yer alır?', '28. madde', ['10. madde', '66. madde', '104. madde ve geçici maddeler'], 'Anayasa m.28 basın hürriyetini düzenler; matbaa kurmak izin alma ve mali teminat yatırma şartına bağlanamaz.'),
  ('Herkesin önceden izin almaksızın silahsız ve saldırısız toplantı ve gösteri yürüyüşü düzenleyebilmesi hangi hakkın kapsamındadır?', 'Toplantı ve gösteri yürüyüşü hakkı', ['Dilekçe hakkı', 'Bilgi edinme hakkı', 'Kamu hizmetine girme hakkı ve memuriyet güvencesi'], 'Anayasa m.34, herkesin önceden izin almaksızın silahsız ve saldırısız toplantı ve gösteri yürüyüşü düzenleyebileceğini öngörür.'),
  ('Bir grup öğretmen, mesleki çıkarlarını korumak için önceden izin almadan bir sendika kurmuştur. Bu durum hangi özgürlüğün kullanılmasıdır?', 'Sendika kurma özgürlüğü', ['Seyahat özgürlüğü', 'Konut dokunulmazlığı', 'Bilim ve sanat hürriyeti'], 'Anayasa m.51\'e göre çalışanlar ve işverenler önceden izin almaksızın sendika ve üst kuruluşlar kurma hakkına sahiptir.'),
  ('Bir gazete hakkında gerçeğe aykırı haber yayımlanan kişi, gazetenin kendi açıklamasını yayımlamasını istemektedir. Bu hakka ne ad verilir?', 'Cevap ve düzeltme hakkı', ['Bilgi edinme hakkı', 'Hak arama hürriyeti', 'Dilekçe hakkı'], 'Anayasa m.32, kişilerin haysiyet ve şereflerine dokunan veya gerçeğe aykırı yayınlar karşısında cevap ve düzeltme hakkını düzenler.'),
  ('"Devletin dini, din-i İslam\'dır" ifadesi Anayasa\'dan hangi yıl çıkarılmıştır?', '1928', ['1924', '1937', '1946 yılında çok partili hayata geçilirken'], '10 Nisan 1928\'de yapılan değişiklikle bu ifade 1924 Anayasası\'ndan çıkarıldı.'),
  ('Laiklik ilkesi Türkiye\'de ilk kez hangi yıl Anayasa\'ya girmiştir?', '1937', ['1928', '1924', '1961 Anayasası\'nın kabulüyle'], '5 Şubat 1937\'deki değişiklikle Atatürk ilkeleri, laiklik de dâhil olmak üzere, Anayasa\'nın 2. maddesine eklendi.'),
  ('Bir devletin kanunlarını din kurallarına göre değil, akıl ve bilim esaslarına ve toplumun ihtiyaçlarına göre yapması hangi ilkenin uygulamasıdır?', 'Laiklik', ['Teokrasi', 'Mutlakiyet', 'Halkçılığın ekonomik boyutu'], 'Laiklik, hukuk düzeninin dinî kurallara değil akla, bilime ve toplumun ihtiyaçlarına dayanmasını gerektirir.'),
  ('1839 Tanzimat Fermanı\'nın hukuk açısından en önemli yeniliği nedir?', 'Padişahın, kendisinin de kanunlara uyacağını kabul etmesi', ['Meclis-i Mebusan\'ın açılması', 'Cumhuriyetin ilan edilmesi', 'Kadınlara seçme ve seçilme hakkı tanınması'], 'Tanzimat Fermanı ile can, mal ve namus güvenliği güvenceye alındı ve kanun üstünlüğü ilkesi ilk kez kabul edildi.'),
  ('I. Meşrutiyet döneminde kurulan Osmanlı parlamentosunun iki kanadı hangileridir?', 'Meclis-i Mebusan ve Meclis-i Ayan', ['Divan-ı Hümayun ve Meclis-i Vala', 'Danıştay ve Yargıtay', 'Senato ve Millet Meclisi'], 'Halkın seçtiği Meclis-i Mebusan ile padişahın atadığı Meclis-i Ayan birlikte Meclis-i Umumi\'yi oluşturuyordu.'),
  ('II. Meşrutiyet\'in ilanından sonra 1909\'da Kanun-i Esasi\'de yapılan değişikliklerin genel yönü nedir?', 'Padişahın yetkileri azaltılmış, meclisin yetkileri artırılmıştır.', ['Meclis tamamen kapatılmıştır.', 'Padişaha meclisi süresiz kapatma yetkisi verilmiştir.', 'Saltanat kaldırılarak cumhuriyet ilan edilmiştir.'], '1909 değişiklikleriyle padişahın sürgün yetkisi kaldırılmış, hükümet meclise karşı sorumlu hâle getirilmiştir.'),
  ('1856 Islahat Fermanı\'nın temel amacı neydi?', 'Gayrimüslim tebaaya yeni haklar tanımak', ['Osmanlı\'da ilk meclisi açmak', 'Padişahlığı kaldırmak', 'Halifeliği Türkiye Büyük Millet Meclisine devretmek ve hilafeti sona erdirmek'], 'Islahat Fermanı, Avrupa devletlerinin baskısıyla gayrimüslimlere Müslümanlarla eşit haklar tanımayı amaçlamıştır.'),
  ('Türkiye Cumhuriyeti\'nin temellerini atan ve 20 Ocak 1921\'de kabul edilen anayasa hangisidir?', 'Teşkilat-ı Esasiye Kanunu', ['Kanun-i Esasi', '1924 Anayasası', 'Misak-ı Millî Beyannamesi ve Amasya Genelgesi'], '1921 Teşkilat-ı Esasiye Kanunu, Kurtuluş Savaşı sırasında TBMM tarafından kabul edilmiş kısa bir anayasadır.'),
  ('1921 Teşkilat-ı Esasiye Kanunu\'nun ilk maddesinde yer alan ve yeni devletin temel ilkesini ortaya koyan ifade hangisidir?', 'Hâkimiyet bilakayd ü şart milletindir.', ['Devletin dini İslam\'dır.', 'Türkiye Devleti bir cumhuriyettir ve halifelik sürer.', 'Padişah kutsaldır ve sorumsuzdur.'], 'Bu ifade millî egemenlik ilkesini anayasal düzeyde ilk kez ilan etmiştir.'),
  ('1921 Teşkilat-ı Esasiye Kanunu\'nun yerel yönetimlere ilişkin dikkat çekici yeniliği hangisidir?', 'Vilayetlere geniş özerklik tanıyan yerinden yönetim anlayışı', ['Belediyelerin tamamen kaldırılması', 'Köylerin doğrudan Saray\'a bağlanması', 'Bütün yerel yöneticilerin halk oylamasıyla atanması ve vali kaldırılması'], '1921 Anayasası vilayetlere manevi şahsiyet ve muhtariyet tanımış, şura denilen seçilmiş meclisler öngörmüştür.'),
  ('1921 Teşkilat-ı Esasiye Kanunu ile Kanun-i Esasi\'nin hangi ilişkiyle bir süre birlikte yürürlükte kaldığı söylenir?', '1921 Anayasası, kendisiyle çelişmeyen Kanun-i Esasi hükümlerini yürürlükten kaldırmamıştır.', ['1921 Anayasası Kanun-i Esasi\'nin tamamını ilk gün yürürlükten kaldırmıştır.', 'Kanun-i Esasi 1921 Anayasası\'ndan daha üstün sayılmıştır.', 'Her iki anayasa da padişah tarafından ilan edilmiştir.'], 'Kısa ve savaş koşullarına göre hazırlanan 1921 Anayasası ile çelişmeyen Kanun-i Esasi hükümleri uygulanmaya devam etmiş; ikili yapı 1924 Anayasası ile sona ermiştir.'),
  ('1924 Anayasası\'nda benimsenen hükümet sistemine ilişkin en doğru değerlendirme hangisidir?', 'Meclis hükümeti ile parlamenter sistemin karma bir örneğidir.', ['Saf başkanlık sistemidir.', 'Mutlak monarşidir.', 'Federal yapıda bir sistemdir.'], '1924 Anayasası\'nda yasama ve yürütme mecliste toplansa da başbakan ve bakanlar kurulu meclise karşı sorumluydu; bu nedenle karma bir sistem kabul edilir.'),
  ('1924 Anayasası döneminde kanunların anayasaya uygunluğunu denetleyen bir mahkemenin bulunmamasının sonucu ne olmuştur?', 'Anayasaya aykırı kanunlar yargısal denetimden geçmeden uygulanabilmiştir.', ['Kanunların tamamı halk oylamasıyla iptal edilmiştir.', 'Yargıtay kanunları iptal edebilmiştir.', 'Kanun çıkarmak imkânsız hâle gelmiştir.'], '1924 Anayasası anayasanın üstünlüğünü ilan etse de bunu güvenceye alacak bir anayasa yargısı kurmamıştır.'),
  ('1924 Anayasası 1934\'teki değişiklikle hangi haktan hangi grubu da yararlandırmıştır?', 'Milletvekili seçme-seçilme hakkından kadınları', ['Askerlik hizmetinden yabancıları', 'Dilekçe hakkından tüzel kişileri', 'Mülkiyet hakkından vakıfları ve azınlık okullarını'], '5 Aralık 1934\'te 1924 Anayasası\'nın seçimle ilgili maddeleri değiştirilerek kadınlara da milletvekili seçme ve seçilme hakkı tanınmıştır.'),
  ('1961 Anayasası\'nı önceki Türk anayasalarından ayıran en belirgin özellik hangisidir?', 'Sosyal hakları geniş biçimde düzenleyip özgürlükçü bir yapı kurması', ['Meclis hükümeti sistemini benimsemesi', 'Saltanatı yeniden kurması', 'Tek partili sistemi zorunlu kılması'], '1961 Anayasası sosyal devlet ilkesini benimsemiş, temel hakları ayrıntılı düzenlemiş, özerk kurumlar ve anayasa yargısı oluşturmuştur.'),
  ('1961 Anayasası\'yla anayasal bir kurum olarak düzenlenen ve özerk yapıya kavuşturulan kurumlardan biri hangisidir?', 'Türkiye Radyo ve Televizyon Kurumu', ['Yüksek Seçim Kurulu Başkanlığı\'na bağlı belediyeler', 'Cumhurbaşkanlığı Hükümet Sistemi', 'Hâkimler ve Savcılar Kurulu'], '1961 Anayasası üniversiteleri ve TRT\'yi özerk kurumlar olarak düzenlemişti. HSK ise 2017 değişikliğiyle bu adı almıştır.'),
  ('1982 Anayasası\'na göre ilk üç maddenin değiştirilemeyeceğini ve değiştirilmesinin teklif dahi edilemeyeceğini öngören madde hangisidir?', '4. madde', ['2. madde', '10. madde', '175. madde'], 'Anayasa m.4, 1. maddedeki devletin şeklinin Cumhuriyet olduğu hükmü ile 2. ve 3. maddelerin değiştirilemeyeceğini öngörür.'),
  ('Devletin, gelir düzeyi düşük vatandaşlara sosyal yardım yapması ve herkes için sosyal güvenlik sistemi kurması Cumhuriyetin hangi niteliğiyle ilgilidir?', 'Sosyal devlet', ['Laik devlet', 'Üniter devlet', 'Hukuk devletinin yargı denetimi boyutu'], 'Sosyal devlet, bireylerin insan onuruna yaraşır bir yaşam sürebilmesi için ekonomik ve sosyal alanda etkin rol üstlenir.'),
  ('Anayasa\'ya göre Cumhuriyetin nitelikleri arasında sayılan "insan haklarına saygılı" olma özelliği devlete hangi yükümlülüğü yükler?', 'Temel hakları tanımak, korumak ve gerçekleştirmek', ['Hakları yalnız savaş dönemlerinde tanımak', 'İnsan haklarını uluslararası örgütlere devretmek', 'Vatandaş olmayanların tüm haklarını kaldırmak'], 'İnsan haklarına saygılı devlet, hakları ihlal etmemekle kalmaz, onları korur ve kullanılabilir hâle getirir.'),
  ('Bir milletvekilinin Meclis Genel Kurulunda yaptığı konuşma nedeniyle sorumlu tutulamaması hangi anayasal güvencedir?', 'Yasama sorumsuzluğu', ['Yasama dokunulmazlığı', 'Masumiyet karinesi', 'Tabii hâkim güvencesi'], 'Anayasa m.83\'e göre milletvekilleri meclis çalışmalarındaki oy ve sözlerinden, Meclisteki düşüncelerinden sorumlu tutulamaz; bu yasama sorumsuzluğudur.'),
  ('TBMM\'de yasama dönemi ile yasama yılı arasındaki fark nedir?', 'Dönem iki genel seçim arasını, yasama yılı ise her yıl Ekim ayında başlayan çalışma yılını ifade eder.', ['Dönem bir ay, yıl ise on iki aydır.', 'Dönem yalnız Senato için, yıl ise Millet Meclisi için kullanılır.', 'İkisi de aynı anlama gelen eş anlamlı kavramlardır ve fark gözetilmez.'], 'Yasama dönemi bir seçimden diğerine kadar geçen süredir; yasama yılı ise Meclisin her yıl Ekim ayının ilk gününde başlayan çalışma dönemidir.'),
  ('Anayasa\'ya göre TBMM toplantılarında kural olarak gerekli olan toplantı yeter sayısı nedir?', 'Üye tamsayısının en az üçte biri', ['Üye tamsayısının salt çoğunluğu', 'Üye tamsayısının üçte ikisi', 'Üye tamsayısının dörtte üçü'], 'Anayasa m.96\'ya göre TBMM üye tamsayısının en az üçte biri ile toplanır ve kural olarak katılanların salt çoğunluğuyla karar verir; karar yeter sayısı üye tamsayısının dörtte birinin bir fazlasından az olamaz.'),
  ('2017 değişikliğinden sonra TBMM\'de kanun teklif etme yetkisi kime aittir?', 'Milletvekillerine', ['Cumhurbaşkanına', 'Bakanlara', 'Yargıtay Birinci Başkanına ve Danıştay Başkanına'], 'Anayasa m.88\'e göre kanun teklif etmeye milletvekilleri yetkilidir; 2017\'den önce Bakanlar Kurulu da kanun tasarısı sunabiliyordu.'),
  ('TBMM\'nin kabul ettiği bir kanunu Cumhurbaşkanı uygun bulmazsa ne yapabilir?', 'Yeniden görüşülmek üzere TBMM\'ye geri gönderebilir.', ['Kanunu doğrudan kendisi değiştirip yayımlar.', 'Kanunu Yargıtay\'a göndererek bozdurur.', 'Kanunu kesin olarak yürürlükten kaldırır, Meclis de bir daha görüşemez ve tartışamaz.'], 'Anayasa m.89\'a göre Cumhurbaşkanı kanunu on beş gün içinde yayımlar ya da yeniden görüşülmek üzere TBMM\'ye geri gönderir.'),
  ('Cumhurbaşkanının geri gönderdiği bir kanun, TBMM\'de değiştirilmeden yeniden kabul edilmek istenirse 2017\'den sonra hangi çoğunluk aranır?', 'Üye tamsayısının salt çoğunluğu', ['Toplantıya katılanların salt çoğunluğu', 'Üye tamsayısının dörtte üçü', 'Toplantıya katılanların üçte biri ve en az yüz milletvekili'], 'Anayasa m.89\'a göre geri gönderilen kanunun aynen kabulü için üye tamsayısının salt çoğunluğu gerekir; o hâlde Cumhurbaşkanı kanunu yayımlar.'),
  ('Seçimden önce veya sonra suç işlediği ileri sürülen bir milletvekilinin, Meclis kararı olmadıkça tutuklanamaması ve yargılanamaması hangi güvencedir?', 'Yasama dokunulmazlığı', ['Yasama sorumsuzluğu', 'Yargı bağımsızlığı', 'Hâkimlik teminatı'], 'Anayasa m.83\'e göre Anayasa\'nın 14. maddesi kapsamına giren ağır cezalık suçüstü hali gibi istisnalar dışında milletvekili Meclis kararı olmadıkça tutulamaz, yargılanamaz.'),
  ('2017 Anayasa değişikliğiyle kabul edilen hükümet sisteminin adı nedir?', 'Cumhurbaşkanlığı hükümet sistemi', ['Parlamenter sistem', 'Meclis hükümeti sistemi', 'Yarı başkanlık sistemi ve iki başlı yürütme'], '16 Nisan 2017 halk oylamasıyla kabul edilen değişiklikle yürütme yetkisi Cumhurbaşkanına verilmiş, Başbakanlık ve Bakanlar Kurulu kaldırılmıştır.'),
  ('2017 değişikliğinden sonra Cumhurbaşkanı yardımcıları ve bakanlar nasıl göreve gelir?', 'Cumhurbaşkanınca atanırlar.', ['TBMM tarafından seçilirler.', 'Halk tarafından seçilirler.', 'Yargıtay Büyük Genel Kurulunca belirlenirler ve yeminle göreve başlarlar.'], 'Anayasa m.104 ve 106\'ya göre Cumhurbaşkanı yardımcılarını ve bakanları atar ve görevden alır.'),
  ('2017 değişikliğine göre bir bakan milletvekilleri arasından atanırsa ne olur?', 'Milletvekilliği sona erer.', ['Hem bakan hem milletvekili olarak görev yapar.', 'Atama geçersiz sayılır.', 'Bir yıl süreyle Meclis üyeliği askıya alınır ve sonra geri döner.'], 'Anayasa m.106\'ya göre milletvekilleri arasından atanan Cumhurbaşkanı yardımcısı ve bakanların milletvekillikleri sona erer.'),
  ('2017 değişikliğinden önce Türkiye\'de Cumhurbaşkanı kaç yıllık görev süresi için seçiliyordu ve halkça seçilmeden önce onu kim seçiyordu?', 'Yedi yıl; TBMM', ['Beş yıl; halk', 'Dört yıl; Danışma Meclisi', 'On yıl; Millî Güvenlik Kurulu ve Bakanlar Kurulu'], '1982 Anayasası\'nın ilk hâlinde Cumhurbaşkanı TBMM tarafından yedi yıl için seçilirdi; 2007 değişikliği halk seçimini ve beş yıllık süreyi getirdi.'),
  ('Anayasa Mahkemesinin kanunların anayasaya uygunluğunu doğrudan, belirli bir dava olmaksızın incelediği yola ne ad verilir?', 'İptal davası (soyut norm denetimi)', ['İtiraz yolu (somut norm denetimi)', 'Bireysel başvuru', 'İstinaf yoluyla yapılan kanun yolu incelemesi'], 'İptal davası, kanunun yayımından sonraki altmış gün içinde Cumhurbaşkanı, iktidar ve ana muhalefet partisi grupları veya üye tamsayısının beşte biri tarafından açılabilir.'),
  ('Bir asliye hukuk mahkemesi, görmekte olduğu davada uygulayacağı kanun hükmünün anayasaya aykırı olduğu kanısına varıyor. Mahkeme ne yapmalıdır?', 'Konuyu itiraz yoluyla Anayasa Mahkemesine götürmeli', ['Kanunu kendisi iptal edip davayı sonuçlandırmalı', 'Davayı Yargıtay\'a göndermeli', 'Hükmü uygulamadan davayı düşürmeli ve dosyayı kapatmalı'], 'Anayasa m.152\'ye göre mahkeme, uygulanacak kuralı anayasaya aykırı görürse Anayasa Mahkemesinin vereceği karara kadar davayı geri bırakır.'),
  ('Anayasa Mahkemesine bireysel başvuru yolu hangi düzenlemeyle getirilmiştir?', '2010 Anayasa değişikliği', ['1961 Anayasası\'nın ilk metni', '1924 Anayasası', '1982 Anayasası\'nın ilk metni ve geçici maddeleri'], '12 Eylül 2010 halk oylamasıyla kabul edilen değişiklikle getirilen bireysel başvuru, 23 Eylül 2012\'den itibaren kullanılmaya başlanmıştır.'),
  ('Anayasa Mahkemesi, anayasa değişikliklerini hangi yönden denetleyebilir?', 'Yalnızca şekil bakımından', ['Yalnızca esas bakımından', 'Hem şekil hem esas bakımından sınırsız', 'Hiçbir yönden denetleyemez ve inceleme talebini reddeder'], 'Anayasa m.148\'e göre anayasa değişikliklerinin incelenmesi teklif ve oylama çoğunluğu ile ivedilikle görüşülememe şartıyla sınırlı olarak şekil bakımından yapılır.'),
  ('Anayasa Mahkemesi Yüce Divan sıfatıyla kimleri yargılar?', 'Görevleriyle ilgili suçlardan Cumhurbaşkanı, bakanlar ve yüksek yargı üyeleri gibi kişileri', ['Trafik kazasına karışan her vatandaşı', 'Yalnızca vergi borcu olan şirketleri', 'Belediye meclis üyelerini ve muhtarları her türlü suçtan'], 'Anayasa m.148\'e göre Cumhurbaşkanı, Cumhurbaşkanı yardımcıları, bakanlar, yüksek mahkeme başkan ve üyeleri gibi kişiler görevleriyle ilgili suçlardan Yüce Divan\'da yargılanır.'),
  ('Anayasa Mahkemesinin iptal kararları için hangisi doğrudur?', 'Kesindir ve bütün devlet organlarını bağlar.', ['Yargıtay\'ın onayından sonra kesinleşir.', 'Sadece davayı açan partiyi bağlar.', 'TBMM\'nin onayıyla yürürlüğe girer, ret hâlinde uygulanmaz.'], 'Anayasa m.153\'e göre Anayasa Mahkemesi kararları kesindir; Resmî Gazete\'de yayımlanır ve yasama, yürütme, idare ile kişileri bağlar.'),
  ('Hâkim ve savcıların mesleğe kabulü, atanması, terfisi ve disiplin işlerine karar veren kurul hangisidir?', 'Hâkimler ve Savcılar Kurulu', ['Yükseköğretim Kurulu', 'Yüksek Seçim Kurulu', 'Devlet Denetleme Kurulu'], 'Anayasa m.159\'a göre HSK, hâkim ve savcıların atama, nakil, terfi ve disiplin işlemlerini yürütür.'),
  ('Hâkimlerin kendi istekleri olmadıkça Anayasa\'da gösterilenlerden önce emekliye ayrılmaya zorlanamaması ve kadrolarının kaldırılması nedeniyle aylıksız bırakılamaması hangi güvencedir?', 'Hâkimlik teminatı', ['Yasama dokunulmazlığı', 'Kamu denetçiliği', 'Masumiyet karinesi'], 'Anayasa m.139\'da düzenlenen hâkimlik ve savcılık teminatı, yargının bağımsızlığını kişisel güvenceyle destekler.'),
  ('Türkiye\'de Cumhurbaşkanlığı hükümet sistemini getiren anayasa değişikliği hangi tarihteki halk oylamasında kabul edilmiştir?', '16 Nisan 2017', ['21 Ekim 2007', '12 Eylül 2010', '6 Eylül 1987 tarihindeki oylamada'], '16 Nisan 2017 halk oylamasında 18 maddelik değişiklik paketi kabul edilmiş ve yeni sistem 2018 seçimleriyle yürürlüğe girmiştir.'),
  ('1987\'de yapılan halk oylamasının konusu neydi?', 'Eski siyasetçilere getirilen siyasi yasakların kaldırılması', ['1982 Anayasası\'nın kabulü', 'Cumhurbaşkanının halkça seçilmesi', 'Yerel seçimlerin bir yıl erken yapılması ve milletvekili sayısı'], '6 Eylül 1987 halk oylamasıyla 1982 Anayasası\'nın geçici 4. maddesindeki siyasi yasaklar az farkla kaldırılmıştır.'),
  ('Anayasa m.175\'e göre bir anayasa değişikliği teklifi TBMM\'de 360 ile 400 arasında oyla kabul edilirse ne olur?', 'Cumhurbaşkanı geri göndermezse halk oylamasına sunulur.', ['Doğrudan yürürlüğe girer, halk oylaması gerekmez.', 'Teklif reddedilmiş sayılır.', 'Anayasa Mahkemesine gönderilip onaylanması beklenir ve sonra yürürlüğe girer.'], 'Üye tamsayısının beşte üçü ile üçte ikisinden az oyla kabul edilen değişiklikler halk oylamasına sunulur; üçte iki ve üzeri oyla kabulde Cumhurbaşkanı halkoyuna sunabilir.'),
  ('Merkezi yönetimin bazı yetkilerini başkentteki örgütü yerine illerdeki temsilcilerine bırakmasına ne ad verilir?', 'Yetki genişliği', ['Yerinden yönetim', 'Kuvvetler ayrılığı', 'Hizmet yerinden yönetimi ve özerk kuruluşlar'], 'Yetki genişliği, merkezi yönetimin içinde bir görev dağılımıdır; vali ve kaymakamlar bu yetkileri merkezin hiyerarşisi altında kullanır.'),
  ('Bir şehirde sokak aydınlatması, çöp toplama ve imar planlarının hazırlanması öncelikle hangi kurumun görevidir?', 'Belediye', ['Valilik', 'Yargıtay', 'Sayıştay'], 'Kentsel ortak ihtiyaçların karşılanması, yerel yönetim birimi olan belediyelerin görev alanındadır.'),
  ('Bir belediye aracının kamu hizmeti sırasında bir vatandaşın aracına zarar verdiği durumda, vatandaşın zararının ödenmesi için açacağı dava hangisidir?', 'Tam yargı davası', ['İptal davası', 'Ceza davası', 'Boşanma davası'], 'Tam yargı davası, idari eylem veya işlemler nedeniyle kişisel hakları doğrudan muhtel olanların açtığı tazminat davasıdır.'),
  ('Vatandaşların idarenin işleyişi hakkındaki şikâyetlerini inceleyen ve halk arasında ombudsman olarak da bilinen kurum Türkiye\'de hangisidir?', 'Kamu Denetçiliği Kurumu', ['Sayıştay', 'Devlet Denetleme Kurulu', 'İçişleri Bakanlığı Mülkiye Teftiş Kurulu'], '2010 değişikliğiyle anayasal dayanak kazanan Kamu Denetçiliği Kurumu 2012\'de kurulmuş ve TBMM Başkanlığına bağlı olarak çalışmaktadır.'),
  ('İdarenin işlemlerinde kamu yararını gözetme zorunluluğu hangi unsurla ilgilidir?', 'Amaç unsuru', ['Şekil unsuru', 'Yetki unsuru', 'Konu unsuru'], 'İdari işlemin beş unsuru yetki, şekil, sebep, konu ve amaçtır; amaç unsuru daima kamu yararıdır.'),
  ('Bir valinin, kanunen bakanın yetkisinde olan bir atamayı kendisi yapması idari işlemin hangi unsurundaki sakatlığa örnektir?', 'Yetki', ['Şekil', 'Amaç', 'Sebep'], 'Kanunun başka bir makama verdiği yetkiyi kullanan makam, yetki unsuru bakımından hukuka aykırı işlem yapmış olur.'),
  ('Anayasa\'nın 66. maddesi "Türk" kavramını hangi ölçüte dayanarak tanımlar?', 'Devlete vatandaşlık bağıyla bağlı olmak', ['Etnik köken ve soy', 'Ana dilinin Türkçe olması', 'Türkiye sınırları içinde doğmuş olmak ve orada yaşamak'], 'Anayasa m.66, "Türk Devletine vatandaşlık bağı ile bağlı olan herkes Türktür." der; tanım etnik değil hukuki bir bağa dayanır.'),
  ('Anayasa\'ya göre vatana bağlılıkla bağdaşmayan bir eylemde bulunmadıkça hiçbir Türk için ne yapılamaz?', 'Vatandaşlıktan çıkarılamaz.', ['Vergiden muaf tutulamaz.', 'Yurt dışına çıkamaz.', 'Seçme hakkı ve dilekçe hakkı kullandırılamaz.'], 'Anayasa m.66\'ya göre vatana bağlılıkla bağdaşmayan bir eylemde bulunmadıkça hiçbir Türk vatandaşlıktan çıkarılamaz.'),
  ('Türk vatandaşlığının sonradan kazanılma yollarından biri hangisidir?', 'Yetkili makam kararı', ['Türk babadan doğma', 'Türk anadan doğma', 'Türkiye\'de doğup vatansız kalma ve nüfusa kayıt'], '5901 sayılı Kanun\'a göre vatandaşlık sonradan yetkili makam kararı, evlat edinilme veya seçme hakkı yoluyla kazanılır; diğerleri doğumla kazanma yollarıdır.'),
  ('Yabancı bir kişinin bir devletin ülkesinde bulunduğu sürece o devletin kanunlarına uymak zorunda olması hangi ilkeyle açıklanır?', 'Ülkesellik ilkesi', ['Vatandaşlık ilkesi', 'Yasama sorumsuzluğu', 'Diplomatik dokunulmazlık ve karşılıklılık ilkesi'], 'Devletin ülkesi üzerindeki egemenliği nedeniyle hukuk kuralları kural olarak o ülkede bulunan herkese uygulanır.'),
  ('Anayasa m.67\'ye göre aşağıdakilerden hangisi kural olarak oy kullanamaz?', 'Taksirli suçlar hariç ceza infaz kurumlarındaki hükümlüler', ['Yurt dışında yaşayan Türk vatandaşları', 'Yeni ergin olmuş 18 yaşındaki üniversite öğrencileri', 'Emekli memurlar'], 'Silah altındaki er ve erbaşlar, askerî öğrenciler ile taksirli suçlardan hükümlüler hariç ceza infaz kurumlarındaki hükümlüler oy kullanamaz.'),
  ('Yurt dışında yaşayan bir Türk vatandaşının bulunduğu ülkede veya gümrük kapılarında oy kullanabilmesi Anayasa\'da hangi ilkeye dayanır?', 'Seçimlerde ve halkoylamasında genel oy ilkesinin yurt dışını kapsaması', ['Ülkesellik ilkesi', 'Kanunların geriye yürümezliği', 'İdari vesayet ve yerinden yönetim'], 'Anayasa m.67\'ye göre yurt dışındaki vatandaşların seçme hakkını kullanabilmesi için kanunla gerekli tedbirler alınır.'),
  ('Anayasa\'ya göre milletvekili seçilebilmek için gerekli koşullardan biri hangisidir?', 'Türk vatandaşı olmak', ['Yükseköğrenim mezunu olmak', 'Kırk yaşını doldurmak', 'Daha önce belediye başkanlığı yapmış olmak ve en az iki dönem görevde kalmak'], 'Anayasa m.76\'ya göre on sekiz yaşını dolduran her Türk milletvekili seçilebilir; en az ilköğretim mezunu olmak gibi şartlar vardır, yükseköğrenim aranmaz.'),
  ('Kamu kurumlarından belge ve bilgi istenebilmesini düzenleyen 4982 sayılı Kanun hangi yıl kabul edilmiştir?', '2003', ['1982', '1995', '2012 yılında Kamu Denetçiliği ile birlikte'], '4982 sayılı Bilgi Edinme Hakkı Kanunu 2003\'te kabul edilmiş, 2004\'te yürürlüğe girmiştir; bilgi edinme hakkı 2010\'da Anayasa m.74\'e de eklenmiştir.'),
  ('Bilgi edinme hakkının sınırları arasında hangisi yer alır?', 'Devlet sırrı niteliğindeki bilgiler', ['Kurumun yıllık faaliyet raporu', 'Kamu ihalelerinin sonuçları', 'Kurumun açık hizmet saatleri ve iletişim bilgileri'], '4982 sayılı Kanun, devlet sırrı, ülkenin ekonomik çıkarları, istihbarat ve kişisel mahremiyet gibi konuları bilgi edinme hakkının kapsamı dışında tutar.'),
  ('Bir kişi, satın aldığı ayıplı bir buzdolabının değiştirilmesini satıcının reddetmesi üzerine başvuru yapmak istiyor. Belli bir parasal sınırın altındaki uyuşmazlıklarda zorunlu ilk başvuru mercii hangisidir?', 'Tüketici hakem heyeti', ['Anayasa Mahkemesi', 'Danıştay', 'Yüksek Seçim Kurulu'], '6502 sayılı Tüketicinin Korunması Hakkında Kanun\'a göre belirlenen parasal sınırın altındaki uyuşmazlıklarda tüketici hakem heyetlerine başvuru zorunludur.'),
  ('Bir kişinin mektuplarının ve telefon görüşmelerinin hâkim kararı olmadan dinlenmesi hangi hakkın ihlalidir?', 'Haberleşme hürriyeti', ['Toplantı hakkı', 'Seçme hakkı', 'Çalışma hakkı ve sözleşme hürriyeti'], 'Anayasa m.22\'ye göre haberleşmenin gizliliği esastır; ancak hâkim kararıyla ve kanunda belirtilen sebeplerle engellenebilir.'),
  ('Kişisel verilerin korunmasını isteme hakkı Anayasa\'ya hangi değişiklikle ve hangi maddeye eklenmiştir?', '2010 değişikliğiyle 20. maddeye', ['2001 değişikliğiyle 10. maddeye', '2017 değişikliğiyle 104. maddeye', '1995 değişikliğiyle 67. maddeye ve geçici bir maddeye'], '2010 değişikliğiyle özel hayatın gizliliğini düzenleyen m.20\'ye kişisel verilerin korunmasını isteme hakkı eklenmiştir; 6698 sayılı KVKK 2016\'da kabul edilmiştir.'),
  ('Anayasa m.17\'ye göre hiç kimseye işkence ve eziyet yapılamaz. Bu yasak hangi hakkın parçasıdır?', 'Kişinin maddi ve manevi bütünlüğü', ['Mülkiyet hakkı', 'Siyasi parti kurma hakkı', 'Seyahat hürriyeti ve yerleşme serbestliği'], 'Anayasa m.17 yaşama hakkını ve kişinin maddi ve manevi varlığını koruma hakkını düzenler; işkence ve insan haysiyetiyle bağdaşmayan ceza yasaktır.'),
  ('Bir vatandaşın yurt içinde dilediği şehre yerleşebilmesi ve yurt dışına çıkabilmesi hangi özgürlüğün kapsamındadır?', 'Yerleşme ve seyahat hürriyeti', ['Haberleşme hürriyeti', 'Dilekçe hakkı', 'Bilim ve sanat hürriyeti'], 'Anayasa m.23 yerleşme ve seyahat hürriyetini düzenler; vatandaşın yurt dışına çıkma hürriyeti suç soruşturması veya kovuşturması sebebiyle ancak hâkim kararıyla sınırlanabilir.'),
  ('Anayasa\'ya göre herkesin sağlıklı ve dengeli bir çevrede yaşama hakkı yanında çevreyi korumak kimin ödevidir?', 'Devletin ve vatandaşların', ['Yalnız belediyelerin', 'Yalnız sanayi kuruluşlarının', 'Yalnız uluslararası çevre örgütlerinin ve Birleşmiş Milletlerin'], 'Anayasa m.56\'ya göre çevreyi geliştirmek, çevre sağlığını korumak ve çevre kirlenmesini önlemek devletin ve vatandaşların ödevidir.'),
  ('Bir işçi sendikasının toplu sözleşme görüşmelerinde anlaşma sağlanamaması üzerine işi bırakma kararı alması hangi hakkın kullanılmasıdır?', 'Grev hakkı', ['Dilekçe hakkı', 'Seçme hakkı', 'Konut dokunulmazlığı'], 'Anayasa m.54\'e göre toplu iş sözleşmesinin yapılması sırasında uyuşmazlık çıkması hâlinde işçiler grev hakkına sahiptir.'),
  ('Anayasa m.58 hangi kesimin korunmasına yönelik özel bir düzenleme içerir?', 'Gençlik', ['Emekliler', 'Çiftçiler', 'Kamu görevlileri ve askerler'], 'Anayasa m.58\'e göre devlet, istiklal ve Cumhuriyetin emanet edildiği gençlerin müspet ilmin ışığında yetişmesini sağlayacak tedbirleri alır.'),
  ('Anayasa\'ya göre angarya yasaktır. Aşağıdakilerden hangisi Anayasa\'ya göre zorla çalıştırma sayılmaz?', 'Olağanüstü hâllerde vatandaşlardan istenecek hizmetler', ['Bir işverenin işçiyi ücret ödemeden çalıştırması', 'Bir kişinin borcu nedeniyle zorla çalıştırılması', 'Bir belediyenin vatandaşları bedelsiz yol yapımına zorlaması'], 'Anayasa m.18\'e göre olağanüstü hâllerde istenecek hizmetler, hükümlülerin çalıştırılması ve ülke ihtiyaçlarının zorunlu kıldığı vatandaşlık ödevi niteliğindeki çalışmalar zorla çalıştırma sayılmaz.'),
  ('Anayasa\'ya göre devletin tarih, kültür ve tabiat varlıklarını koruma ödevi hangi amaca yöneliktir?', 'Bu değerlerin korunmasını ve gelecek kuşaklara aktarılmasını sağlamak', ['Bu varlıkların yurt dışına satılmasını kolaylaştırmak', 'Bu varlıkları yalnızca turizme açmak', 'Bu varlıkların bakımını tamamen özel kişilere bırakmak ve vergiden muaf tutmak'], 'Anayasa m.63\'e göre devlet, tarih, kültür ve tabiat varlıklarının ve değerlerinin korunmasını sağlar, bu amaçla destekleyici ve özendirici tedbirler alır.'),
  ('Türk Medeni Kanunu m.2\'ye göre herkesin haklarını kullanırken ve borçlarını yerine getirirken uyması gereken kural hangisidir?', 'Dürüstlük kuralı', ['Kanunilik ilkesi', 'Hiyerarşi ilkesi', 'Masumiyet karinesi ve suçta şahsilik'], 'TMK m.2\'ye göre herkes haklarını kullanırken ve borçlarını yerine getirirken dürüstlük kurallarına uymak zorundadır; bir hakkın açıkça kötüye kullanılmasını hukuk düzeni korumaz.'),
  ('Türk Medeni Kanunu m.6\'ya göre bir davada iddia edilen olguyu kim ispat etmek zorundadır?', 'Kanunda aksine hüküm yoksa o olguya dayanarak hak çıkaran taraf', ['Her durumda davalı taraf', 'Her durumda mahkeme', 'Davaya katılan tanıklar ve bilirkişiler ortaklaşa'], 'TMK m.6\'ya göre kanunda aksine bir hüküm bulunmadıkça taraflardan her biri hakkını dayandırdığı olguların varlığını ispatla yükümlüdür.'),
  ('Bir kişinin trafikte dikkatsizlik nedeniyle başkasının arabasına zarar vermesi borcun hangi kaynağına örnektir?', 'Haksız fiil', ['Sözleşme', 'Sebepsiz zenginleşme', 'Vekâlet ve vesayet ilişkisi'], 'Hukuka aykırı ve kusurlu bir fiille başkasına zarar verilmesi haksız fiildir ve zararı tazmin borcunu doğurur.'),
  ('Bir kişinin yanlışlıkla başkasının hesabına para yatırması hâlinde parayı alanın bunu geri vermesi gerektiği hangi kurumla açıklanır?', 'Sebepsiz zenginleşme', ['Haksız fiil', 'Bağışlama', 'Sözleşmeden doğan borç'], 'Haklı bir sebep olmaksızın başkasının malvarlığından zenginleşen kişi, bu zenginleşmeyi geri vermekle yükümlüdür.'),
  ('Kendisine yönelik ani ve haksız bir saldırıyı o anda orantılı biçimde engelleyen kişi hangi hukuka uygunluk sebebinden yararlanır?', 'Meşru savunma', ['Zorunluluk hâli', 'Hakkın kullanılması', 'Kanun hükmünün yerine getirilmesi'], 'TCK m.25\'e göre kendisine veya başkasına yönelik gerçekleşen ya da tekrarı muhakkak olan haksız bir saldırıyı orantılı biçimde def eden kişiye ceza verilmez.'),
  ('Türk Medeni Kanunu\'na göre olağan durumda erkek veya kadın kaç yaşını doldurmadıkça evlenemez?', '17', ['15', '16', '18'], 'TMK m.124\'e göre erkek veya kadın on yedi yaşını doldurmadıkça evlenemez; hâkim olağanüstü durumlarda ve çok önemli bir sebeple on altı yaşını dolduranların evlenmesine izin verebilir.'),
  ('Türkiye Avrupa Konseyine hangi yıl üye olmuştur?', '1949', ['1952', '1963', '1987 yılında tam üyelik başvurusuyla'], 'Mayıs 1949\'da kurulan Avrupa Konseyine Türkiye aynı yılın ağustos ayında katılmıştır.'),
  ('Devletler arasındaki hukuki uyuşmazlıkları çözen ve Birleşmiş Milletler\'in temel yargı organı olan mahkeme hangisidir?', 'Uluslararası Adalet Divanı', ['Avrupa İnsan Hakları Mahkemesi', 'Avrupa Birliği Adalet Divanı', 'Uluslararası Ceza Mahkemesi\'nin Strazburg\'daki Daireleri'], 'Lahey\'de bulunan Uluslararası Adalet Divanı, BM Şartı ile kurulmuş olup devletler arası uyuşmazlıklara bakar.'),
  ('Mültecilerin hukuki statüsünü belirleyen ve geri göndermeme ilkesini içeren temel uluslararası belge hangisidir?', '1951 Cenevre Sözleşmesi', ['1919 Versay Antlaşması', '1648 Vestfalya Barışı', '1923 Lozan Antlaşması ve ekleri'], '1951 tarihli Mültecilerin Hukuki Durumuna İlişkin Sözleşme, zulüm tehlikesi olan ülkeye geri göndermeme ilkesini düzenler.'),
  ('Savaşta yaralılar, esirler ve siviller gibi çatışmaya katılmayanları korumayı amaçlayan hukuk dalına ne ad verilir?', 'Uluslararası insancıl hukuk', ['Anayasa hukuku', 'Vergi hukuku', 'Ticaret hukuku ve deniz ticareti'], '1949 Cenevre Sözleşmeleri başta olmak üzere insancıl hukuk, silahlı çatışmalarda insan onurunu korumak için savaşın yöntemlerini sınırlar.'),
  ('II. Dünya Savaşı\'ndan sonra kurulan Nürnberg Mahkemesinin uluslararası hukuk açısından önemi nedir?', 'Devlet adına suç işleyen kişilerin bireysel olarak yargılanabileceğini göstermesi', ['Savaşın hukuka uygun bir yol olduğunu ilan etmesi', 'Birleşmiş Milletler\'i kurması', 'İnsan Hakları Evrensel Beyannamesi\'ni doğrudan yürürlüğe koyması ve tüm devletlerce imzalanması'], 'Nürnberg yargılamaları, devlet görevlilerinin "emir aldım" savunmasıyla sorumluluktan kurtulamayacağını ve insanlığa karşı suçlardan bizzat sorumlu tutulabileceğini ortaya koydu.'),
  ('Avrupa Konseyi tarafından 1961\'de kabul edilen ve ekonomik ve sosyal hakları güvenceye alan belge hangisidir?', 'Avrupa Sosyal Şartı', ['Avrupa İnsan Hakları Sözleşmesi', 'Maastricht Antlaşması', 'Helsinki Nihai Senedi ve Paris Şartı'], 'Avrupa Sosyal Şartı, AİHS\'nin medeni ve siyasi haklar alanındaki korumasını sosyal haklar alanında tamamlar.'),
  ('Birleşmiş Milletler sisteminde insan hakları alanında çalışan ve bugünkü adıyla İnsan Hakları Konseyi\'nin bağlı olduğu ana organ hangisidir?', 'Genel Kurul', ['Güvenlik Konseyi', 'Uluslararası Adalet Divanı', 'Vesayet Konseyi ve Sekreterya birlikte'], '2006\'da kurulan İnsan Hakları Konseyi, BM Genel Kurulunun yardımcı organıdır ve İnsan Hakları Komisyonunun yerini almıştır.'),
  ('Avrupa Konseyinin anayasa hukuku alanında devletlere danışmanlık yapan ve "Hukuk Yoluyla Demokrasi İçin Avrupa Komisyonu" olarak bilinen organı hangisidir?', 'Venedik Komisyonu', ['Avrupa Komisyonu', 'Bakanlar Komitesi', 'Avrupa Parlamentosu\'nun anayasa komisyonu'], 'Venedik Komisyonu, anayasa ve seçim mevzuatı gibi konularda üye devletlere görüş bildiren danışma organıdır.'),
  ('1995 anayasa değişikliğiyle seçmen yaşı kaçtan kaça indirilmiştir?', '21\'den 18\'e', ['25\'ten 21\'e', '20\'den 19\'a', '22\'den 20\'ye ve 30\'dan 25\'e'], '1982 Anayasası\'nın ilk metninde 21 olan seçmen yaşı 1995 değişikliğiyle 18\'e indirilmiştir.'),
  ('2017 değişiklikleriyle askerî yargıya ilişkin olarak hangi düzenleme yapılmıştır?', 'Disiplin mahkemeleri dışında askerî mahkemeler kaldırılmıştır.', ['Askerî Yargıtay\'ın yetkileri genişletilmiştir.', 'Askerî mahkemeler sivilleri yargılamaya başlamıştır.', 'Askerî Yüksek İdare Mahkemesi\'nin üye sayısı artırılmış ve Danıştay\'a bağlanmıştır.'], '2017 değişikliğiyle Askerî Yargıtay ve Askerî Yüksek İdare Mahkemesi kaldırılmış, savaş hali dışında askerî mahkeme kurulamayacağı öngörülmüştür.'),
  ('1982 Anayasası\'nı hazırlayan Kurucu Meclis hangi iki organdan oluşuyordu?', 'Millî Güvenlik Konseyi ve Danışma Meclisi', ['Millet Meclisi ve Cumhuriyet Senatosu', 'TBMM ve Bakanlar Kurulu', 'Yargıtay ve Danıştay Başkanlar Kurulu'], '12 Eylül 1980\'den sonra kurulan Kurucu Meclis, Millî Güvenlik Konseyi ile Danışma Meclisi\'nden oluşmuş ve Anayasa\'yı hazırlamıştır.'),
  ('1982 Anayasası\'nın ilk hâliyle 1961 Anayasası\'na göre daha çok hangi değeri öne çıkardığı kabul edilir?', 'Devlet otoritesini', ['Mahallî yönetimlerin özerkliğini', 'Üniversitelerin tam özerkliğini', 'Basının sınırsız ve denetimsiz özgürlüğünü'], '1982 Anayasası, 1970\'lerin siyasal çatışma ortamına tepki olarak yürütmeyi güçlendirmiş ve hakları sınırlama sebeplerini genişletmiştir; sonraki değişikliklerle bu yapı yumuşatılmıştır.'),
  ('1982 Anayasası kabul edildiğinde yasama organının yapısı nasıldı?', 'Tek meclisli', ['İki meclisli', 'Üç meclisli', 'Mecliste senato ve halk temsilcileri'], '1982 Anayasası, 1961\'deki iki meclisli yapıyı bırakarak tek meclisli TBMM\'ye dönmüştür.'),
  ('1961 Anayasası\'nın hazırlanmasına zemin hazırlayan olay hangisidir?', '27 Mayıs 1960 askerî müdahalesi', ['12 Mart 1971 muhtırası', '12 Eylül 1980 askerî müdahalesi', '28 Şubat 1997 Millî Güvenlik Kurulu kararları ve sonrası'], '27 Mayıs 1960 müdahalesinin ardından kurulan Kurucu Meclis, Millî Birlik Komitesi ve Temsilciler Meclisi\'nden oluşarak 1961 Anayasası\'nı hazırlamıştır.'),
  ('Türk anayasa tarihinde resmî adı "Teşkilat-ı Esasiye Kanunu" olan anayasalar hangileridir?', '1921 ve 1924 anayasaları', ['1876 ve 1921 anayasaları', '1961 ve 1982 anayasaları', '1924 ve 1961 anayasaları ile 1909 değişiklikleri'], 'Hem 1921 hem 1924 anayasaları Teşkilat-ı Esasiye Kanunu adını taşır; 1876 anayasası Kanun-i Esasi\'dir, 1961 ve 1982 metinleri ise Türkiye Cumhuriyeti Anayasası adını taşır.'),
  ('Türk anayasalarının kronolojik sırası hangisinde doğru verilmiştir?', 'Kanun-i Esasi, Teşkilat-ı Esasiye, 1924, 1961, 1982', ['Teşkilat-ı Esasiye, Kanun-i Esasi, 1924, 1961, 1982', 'Kanun-i Esasi, 1924, Teşkilat-ı Esasiye, 1982, 1961', '1924, Kanun-i Esasi, 1961, Teşkilat-ı Esasiye, 1982'], 'Sıralama 1876 Kanun-i Esasi, 1921 Teşkilat-ı Esasiye, 1924, 1961 ve 1982 anayasaları şeklindedir.'),
  ('1924 Anayasası\'nda egemenliğin kayıtsız şartsız millete ait olduğu ve milletin bu egemenliği hangi organ eliyle kullandığı belirtilmiştir?', 'TBMM', ['Cumhurbaşkanı', 'Bakanlar Kurulu', 'Danıştay ve bağımsız mahkemeler'], '1924 Anayasası\'na göre millet, egemenlik hakkını yalnızca kendisini temsil eden TBMM eliyle kullanırdı.'),
  ('Anayasa\'ya göre yükseköğretim kurumlarının planlanması, düzenlenmesi ve denetlenmesi görevini hangi kurul üstlenir?', 'Yükseköğretim Kurulu', ['Millî Eğitim Şûrası', 'Türkiye Bilimler Akademisi', 'Hâkimler ve Savcılar Kurulu ile Danıştay'], 'Anayasa m.131\'e göre YÖK, yükseköğretim kurumlarının öğretimini planlar, düzenler, yönetir ve denetler.'),
  ('Anayasa m.136\'ya göre genel idare içinde yer alan ve laiklik ilkesi doğrultusunda görev yapan kurum hangisidir?', 'Diyanet İşleri Başkanlığı', ['Vakıflar Genel Müdürlüğü', 'Kültür ve Turizm Bakanlığı', 'Türk Tarih Kurumu ve Türk Dil Kurumu'], 'Anayasa m.136\'ya göre Diyanet İşleri Başkanlığı, laiklik ilkesi doğrultusunda, bütün siyasi görüş ve düşüncelerin dışında kalarak millî dayanışma ve bütünleşmeyi amaç edinir.'),
  ('Anayasa m.134\'te düzenlenen ve Atatürk Kültür Merkezi, Türk Dil Kurumu ve Türk Tarih Kurumunu çatısı altında toplayan kuruluş hangisidir?', 'Atatürk Kültür, Dil ve Tarih Yüksek Kurumu', ['Yükseköğretim Kurulu', 'Kültür ve Turizm Bakanlığı', 'Türkiye Bilimsel ve Teknolojik Araştırma Kurumu'], '1983\'te kurulan Atatürk Kültür, Dil ve Tarih Yüksek Kurumu, anayasal bir kurum olarak Atatürk\'ün manevi himayesinde faaliyet gösterir.'),
  ('2017 değişikliğinden sonra Devlet Denetleme Kurulu hangi makama bağlıdır?', 'Cumhurbaşkanlığı', ['TBMM Başkanlığı', 'Sayıştay', 'Adalet Bakanlığı ve Yargıtay'], 'Anayasa m.108\'e göre idarenin hukuka uygunluğunu, düzenli ve verimli işleyişini denetleyen Devlet Denetleme Kurulu Cumhurbaşkanlığına bağlıdır.'),
  ('Bir davada sanığı savunan, hukuki bilgisini müvekkilinin hakları için kullanan ve bağımsız bir meslek mensubu olan kişi kimdir?', 'Avukat', ['Savcı', 'Hâkim', 'Zabıt kâtibi ve icra memuru'], 'Avukat, yargının kurucu unsurlarından biri olan bağımsız savunmayı temsil eder; savcı iddia, hâkim ise karar makamıdır.'),
  ('Bir kişi bir evi satın alırken sözleşmenin resmî biçimde yapılması için tapu müdürlüğüne gitmektedir. Taşınmaz satış sözleşmesinin geçerli olması için hangi şekil şartı aranır?', 'Resmî şekil', ['Sözlü anlaşma yeterlidir', 'Adi yazılı şekil', 'Sadece tanık huzurunda el sıkışma'], 'TMK ve Türk Borçlar Kanunu\'na göre taşınmaz satış sözleşmesinin geçerliliği resmî şekilde, yani tapu memuru önünde yapılmasına bağlıdır.'),
  ('Yargılamada hukuki veya teknik özel bilgi gerektiren konularda mahkemeye rapor veren kişiye ne ad verilir?', 'Bilirkişi', ['Arabulucu', 'Tanık', 'Hakem ve uzlaştırmacı'], 'Bilirkişi, çözümü hâkimlik mesleği dışında özel veya teknik bilgiyi gerektiren konularda mahkemeye oy ve görüş bildirir.'),
  ('Ceza hukukunda kıyas yasağı neyi ifade eder?', 'Kanunda suç olarak tanımlanmayan bir eylemin, benzer bir suça benzetilerek cezalandırılamamasını', ['Mahkemelerin karar gerekçesi yazmamasını', 'Suçların yalnız savcılık tarafından soruşturulmasını', 'Cezaların her zaman en alt sınırdan verilmesini ve indirim yapılmasını'], 'TCK m.2\'ye göre suç ve ceza içeren hükümler kıyas yoluyla genişletilerek uygulanamaz.'),
  ('2017 değişikliğinden sonra TBMM\'nin bilgi edinme ve denetim yolları arasında hangisi yer almaz?', 'Gensoru', ['Meclis araştırması', 'Genel görüşme', 'Yazılı soru'], 'Anayasa m.98\'e göre TBMM; meclis araştırması, genel görüşme, meclis soruşturması ve yazılı soru yollarıyla denetim yapar. Gensoru 2017 değişikliğiyle kaldırılmıştır.'),
  ('Bakanlar hakkında görevleriyle ilgili suç iddiasıyla soruşturma açılması önerisi TBMM\'de hangi yolla yapılır?', 'Meclis soruşturması', ['Genel görüşme', 'Meclis araştırması', 'Yazılı soru ve sözlü soru'], 'Anayasa m.106\'ya göre TBMM üye tamsayısının salt çoğunluğunun önergesiyle Cumhurbaşkanı yardımcıları ve bakanlar hakkında soruşturma açılması istenebilir.'),
  ('2017 değişikliğinden sonra Anayasa\'ya göre olağanüstü hal ilan etme yetkisi kime aittir?', 'Cumhurbaşkanı', ['TBMM Başkanı', 'Anayasa Mahkemesi', 'Millî Güvenlik Kurulu ve İçişleri Bakanlığı'], 'Anayasa m.119\'a göre Cumhurbaşkanı olağanüstü hal ilan edebilir; karar aynı gün Resmî Gazete\'de yayımlanır ve TBMM\'nin onayına sunulur.'),
  ('Cumhurbaşkanının sürekli hastalık, sakatlık ve kocama sebebiyle belirli kişilerin cezalarını hafifletmesi veya kaldırması hangi yetkisidir?', 'Özel af', ['Genel af', 'Veto', 'Fesih ve seçim yenileme'], 'Anayasa m.104\'e göre Cumhurbaşkanı sürekli hastalık, sakatlık ve kocama sebebiyle belirli kişilerin cezalarını hafifletebilir veya kaldırabilir; genel af ise TBMM\'nin yetkisindedir.'),
  ('Türkiye adına yapılan uluslararası antlaşmaların onaylanmasının kural olarak hangi koşula bağlı olduğu Anayasa m.90\'da belirtilir?', 'TBMM\'nin onaylamayı bir kanunla uygun bulması', ['Halk oylamasında kabul edilmesi', 'Yargıtay\'ın olumlu görüş vermesi', 'Antlaşmanın Resmî Gazete\'de değil, diplomatik bültende yayımlanması'], 'Anayasa m.90\'a göre uluslararası antlaşmaların onaylanması TBMM\'nin onaylamayı bir kanunla uygun bulmasına bağlıdır; bazı ekonomik ve teknik antlaşmalar istisnadır.'),
  ('Anayasa\'ya göre bir memurun görevini kötüye kullanarak bir vatandaşa zarar vermesi hâlinde vatandaş tazminat davasını kural olarak kime karşı açar?', 'İdareye', ['Memura doğrudan', 'Memurun ailesine', 'Memurun bağlı olduğu sendikaya'], 'Anayasa m.129\'a göre kamu görevlilerinin yetkilerini kullanırken işledikleri kusurlardan doğan tazminat davaları idare aleyhine açılır; idare sonra memura rücu edebilir.'),
  ('İnsan Hakları Evrensel Beyannamesi\'ndeki hakları bağlayıcı hâle getirmek için 1966\'da kabul edilen iki BM sözleşmesi hangi alanları düzenler?', 'Medeni ve siyasi haklar ile ekonomik, sosyal ve kültürel haklar', ['Çocuk hakları ile kadın hakları', 'Mülteci hakları ile vatansızlık', 'Silahsızlanma ile nükleer enerji ve uzay hukuku'], '1966\'da kabul edilen Medeni ve Siyasi Haklar Uluslararası Sözleşmesi ile Ekonomik, Sosyal ve Kültürel Haklar Uluslararası Sözleşmesi, Beyanname ile birlikte Uluslararası İnsan Hakları Belgesi\'ni oluşturur.'),
  ('Engellilerin haklarını güvence altına alan Birleşmiş Milletler sözleşmesi hangi yıl kabul edilmiştir?', '2006', ['1989', '1979', '1951 yılında mülteci sözleşmesiyle birlikte'], 'BM Engelli Hakları Sözleşmesi 2006\'da kabul edilmiş, erişilebilirlik ve topluma tam katılım ilkelerini öne çıkarmıştır.'),
  ('BM Engelli Hakları Sözleşmesi\'nin öne çıkardığı "makul düzenleme" kavramı neyi ifade eder?', 'Engelli bireylerin haklardan eşit yararlanması için gerekli ve orantısız yük getirmeyen uyarlamaları', ['Engellilerin ayrı kurumlarda yaşamasını', 'Engellilerin oy hakkının kaldırılmasını', 'Engelli bireylerin çalışma hayatından tümüyle çıkarılmasını'], 'Makul düzenleme, örneğin bir binaya rampa yapılması gibi, eşitliği sağlamak için yapılan uygun değişikliklerdir; yapılmaması ayrımcılık sayılır.'),
  ('Her Türlü Irk Ayrımcılığının Ortadan Kaldırılmasına Dair Uluslararası Sözleşme hangi örgüt tarafından kabul edilmiştir?', 'Birleşmiş Milletler', ['Avrupa Birliği', 'NATO', 'İslam İşbirliği Teşkilatı ve Arap Birliği'], 'Sözleşme 1965\'te BM Genel Kurulunca kabul edilmiş, ırk, renk, soy veya etnik kökene dayalı ayrımcılığı yasaklamıştır.'),
  ('Otoriter rejimleri totaliter rejimlerden ayıran temel özellik hangisidir?', 'Siyasal muhalefeti bastırsalar da toplumsal hayatın her alanını denetlemeye çalışmamaları', ['Serbest ve rekabetçi seçimler yapmaları', 'Yargı bağımsızlığını tam olarak güvenceye almaları', 'Bütün siyasi partilere eşit fırsat tanımaları'], 'Otoriter rejimler siyasal gücü tekelleştirir; ancak totaliter rejimlerdeki gibi bireyin özel ve toplumsal hayatını bütünüyle denetleme ve ideolojik seferberlik hedeflemezler.'),
  ('Halkın yalnız seçimlerde değil, karar alma süreçlerine sürekli katılımını savunan demokrasi anlayışına ne ad verilir?', 'Katılımcı demokrasi', ['Mutlakiyet', 'Teokrasi', 'Oligarşi ve seçkinler yönetimi'], 'Katılımcı demokrasi; halk toplantıları, kamuoyu görüşmeleri ve sivil toplum aracılığıyla vatandaşların karar süreçlerinde etkin rol almasını öngörür.'),
  ('Bir ülkede devlet başkanı ve meclis seçilmekle birlikte, kanunların din adamlarından oluşan bir kurulun onayına bağlı olduğu ve hukukun dinî kurallara dayandığı görülüyor. Bu yapı en çok hangi yönetim anlayışını yansıtır?', 'Teokrasi', ['Laik cumhuriyet', 'Meşruti monarşi', 'Konfederasyon ve federal yapı'], 'Teokraside devlet yönetimi ve hukuk dinî kurallara ve din adamlarının otoritesine dayanır; laik devlet anlayışının tam karşıtıdır.'),
  ('Okul meclisi seçimlerinde aday olan bir öğrenci, seçimi kaybettikten sonra sonucu kabul edip kazanan arkadaşını tebrik ediyor. Bu davranış hangi demokratik ilkeyle en çok ilgilidir?', 'Seçim sonuçlarına saygı ve barışçıl iktidar değişimi', ['Kuvvetler birliği', 'Mutlak egemenlik', 'Kanunların geriye yürümezliği ve hukuki güvenlik'], 'Demokrasi, kaybedenlerin sonuçları meşru kabul etmesine ve iktidarın barışçıl yollarla el değiştirmesine dayanır.'),
  ('Bir belediyenin yeni bir park projesini uygulamaya koymadan önce mahalle sakinleriyle toplantı düzenleyip görüşlerini alması hangi ilkenin uygulamasıdır?', 'Yönetime katılım ve şeffaflık', ['Kuvvetler birliği', 'Merkeziyetçilik', 'İdari vesayet ve hiyerarşik denetim'], 'Karar sürecine ilgili tarafların katılması, yerel demokrasiyi ve yönetimin meşruiyetini güçlendirir.'),
  ('Bir hukuk kuralının yürürlükten kaldırılmasının yollarından biri olan "örtülü ilga" ne anlama gelir?', 'Yeni kuralın eskisiyle çelişmesi nedeniyle eski kuralın uygulanamaz hâle gelmesi', ['Kanunun hangi maddelerin kaldırıldığını tek tek sayması', 'Kanunun Anayasa Mahkemesince iptal edilmesi', 'Kanunun halk oylamasıyla reddedilmesi'], 'Açık ilgada yeni kanun eski hükmü açıkça kaldırır; örtülü ilgada ise aynı konuyu farklı düzenleyen sonraki kanun önceki kanunun uygulanmasını engeller.'),
  ('Hukuk kurallarının zamanla değişebilmesinin temel nedeni hangisidir?', 'Toplumsal ihtiyaçların ve değerlerin değişmesi', ['Kuralların hiçbir zaman yazılı olmaması', 'Hâkimlerin her yıl yeni kanun yazması', 'Ahlak kurallarının tamamen ortadan kalkması ve dinin etkisinin bitmesi'], 'Hukuk toplumun düzenini sağlamak için vardır; toplum yapısı, teknoloji ve değerler değiştikçe kurallar da yeniden düzenlenir.'),
  ('On dört yaşındaki bir çocuk, ailesinin haberi olmadan pahalı bir telefon satın alma sözleşmesi yapmıştır. Bu sözleşmenin geçerliliği kural olarak neye bağlıdır?', 'Yasal temsilcisinin rızasına', ['Satıcının iyi niyetine', 'Telefonun fiyatının düşük olmasına', 'Çocuğun okulundaki öğretmenin onayına'], 'Ayırt etme gücüne sahip küçükler sınırlı ehliyetsizdir; kendilerini borç altına sokan işlemler için yasal temsilcinin rızası gerekir.'),
  ('Akıl hastalığı, savurganlık veya alkol bağımlılığı gibi sebeplerle bir yetişkinin fiil ehliyetinin mahkeme kararıyla sınırlanmasına ne ad verilir?', 'Kısıtlama', ['Ergin kılınma', 'Evlat edinme', 'Velayetin kaldırılması ve kayyım'], 'TMK m.405 vd. kısıtlama sebeplerini düzenler; kısıtlanan kişiye vasi atanır.'),
  ('29 Ekim 1923\'te 1921 Teşkilat-ı Esasiye Kanunu\'nda yapılan değişikliğin anayasal sonucu ne olmuştur?', 'Devletin yönetim şekli Cumhuriyet olarak belirlenmiştir.', ['Halifelik kaldırılmıştır.', 'Kadınlara seçme hakkı tanınmıştır.', 'Çok partili hayata geçilmiş ve ilk serbest seçim yapılmıştır.'], '29 Ekim 1923\'teki değişiklikle "Türkiye Devleti\'nin hükümet şekli Cumhuriyettir" hükmü eklenmiş ve Mustafa Kemal ilk Cumhurbaşkanı seçilmiştir.'),
  ('Halifeliğin kaldırılması ve Şer\'iye Vekâletinin lağvı hangi tarihte kabul edilmiştir?', '3 Mart 1924', ['1 Kasım 1922', '10 Nisan 1928', '17 Şubat 1926 tarihinde'], '3 Mart 1924\'te halifelik kaldırılmış, aynı gün Tevhid-i Tedrisat Kanunu kabul edilmiş ve Şer\'iye ve Evkaf Vekâleti lağvedilmiştir.'),
  ('Cumhuriyet döneminde kurulan ilk muhalefet partisi hangisidir?', 'Terakkiperver Cumhuriyet Fırkası', ['Serbest Cumhuriyet Fırkası', 'Demokrat Parti', 'Millî Kalkınma Partisi ve Ahali Fırkası'], '1924\'te kurulan Terakkiperver Cumhuriyet Fırkası, Şeyh Said İsyanı\'nın ardından 1925\'te kapatılmıştır.'),
  ('1930\'da Atatürk\'ün isteğiyle Fethi Okyar tarafından kurulan ve kısa süre sonra kendini fesheden parti hangisidir?', 'Serbest Cumhuriyet Fırkası', ['Terakkiperver Cumhuriyet Fırkası', 'Demokrat Parti', 'Halk Fırkası ve Cumhuriyet Halk Fırkası'], 'Serbest Cumhuriyet Fırkası 12 Ağustos 1930\'da kurulmuş, aynı yılın kasım ayında kendini feshetmiştir.'),
  ('1945\'te Celal Bayar, Adnan Menderes, Refik Koraltan ve Fuat Köprülü\'nün CHP grubuna verdiği ve daha geniş demokratik haklar isteyen önerge hangi adla bilinir?', 'Dörtlü Takrir', ['Amasya Genelgesi', 'Misak-ı Millî', 'Erzurum Kongresi kararları ve Sivas beyannamesi'], 'Dörtlü Takrir\'in reddedilmesinin ardından önergeyi verenler 1946\'da Demokrat Parti\'yi kurmuştur.'),
  ('Türk Ticaret Kanunu ve Borçlar Kanunu\'nun kabul edildiği 1926 yılında hangi kanunlar örnek alınmıştır?', 'Borçlar Kanunu için İsviçre, Ticaret Kanunu için Alman ve İtalyan kanunları', ['Her ikisi için de İngiliz örf hukuku', 'Her ikisi için de Fransız Medeni Kanunu', 'Borçlar için Rus, Ticaret için Japon kanunları'], 'Borçlar Kanunu İsviçre Borçlar Kanunu\'ndan, Ticaret Kanunu ise Alman ve İtalyan ticaret kanunlarından yararlanılarak hazırlanmıştır.'),
  ('Bir hastane, tedavi ettiği bir hastanın sağlık bilgilerini izni olmadan bir reklam şirketiyle paylaşmıştır. Bu olayda öncelikle hangi hak ihlal edilmiştir?', 'Kişisel verilerin korunmasını isteme hakkı', ['Seçme ve seçilme hakkı', 'Toplantı hakkı', 'Mülkiyet hakkı ve miras hakkı'], 'Sağlık verileri özel nitelikli kişisel verilerdir; ilgili kişinin açık rızası olmadan üçüncü kişilerle paylaşılması Anayasa m.20 ve KVKK\'ya aykırıdır.'),
  ('Bir belediye, yalnızca belirli bir mezhebe mensup kişilerin başvurabileceği bir iş ilanı yayımlamıştır. Bu ilan Anayasa\'nın hangi hükmüne aykırıdır?', 'Kanun önünde eşitlik', ['Vergi ödevi', 'Yasama dokunulmazlığı', 'Seçimlerin beş yılda bir yapılması'], 'Anayasa m.10\'a göre din ve mezhep ayrımı yapılamaz; devlet organları ve idare makamları bütün işlemlerinde eşitlik ilkesine uygun hareket etmek zorundadır.'),
  ('Bir yazar, hükümeti eleştiren bir köşe yazısı nedeniyle gazetesinin işinden çıkarılması için bakanlıkça baskı yapıldığını iddia ediyor. Bu iddia doğruysa öncelikle hangi özgürlüğe müdahale söz konusudur?', 'Basın ve ifade özgürlüğü', ['Seyahat özgürlüğü', 'Din ve vicdan özgürlüğü', 'Konut dokunulmazlığı ve özel hayat'], 'Kamu otoritesinin eleştirel yazılar nedeniyle baskı uygulaması, düşünceyi açıklama ve basın özgürlüğüne doğrudan bir müdahaledir.'),
  ('Bir köyde yaşayan halk, köy yakınına kurulacak bir maden ocağının çevreye zarar vereceğini düşünerek idare mahkemesinde dava açmıştır. Bu davanın dayandığı temel anayasal hak hangisidir?', 'Sağlıklı ve dengeli bir çevrede yaşama hakkı', ['Kamu hizmetine girme hakkı', 'Grev hakkı', 'Seçme hakkı ve siyasi parti üyeliği'], 'Anayasa m.56\'daki çevre hakkı, kişilere çevreyi bozabilecek idari işlemlere karşı yargı yoluna başvurma imkânı verir.'),
  ('Bir vatandaş, valiliğe başvurarak mahallesindeki okulun bakımsızlığından şikâyet ediyor ve sonuçtan yazılı olarak haberdar edilmeyi istiyor. Bu başvuru hangi hakkın kullanımıdır?', 'Dilekçe hakkı', ['Grev hakkı', 'Bireysel başvuru hakkı', 'Hak arama hürriyeti ve dava açma'], 'Anayasa m.74\'e göre vatandaşlar dilek ve şikâyetleri hakkında yetkili makamlara yazıyla başvurabilir; sonuç gecikmeksizin yazılı bildirilir.'),
  ('Bir işveren, sendikaya üye olan işçilerini işten çıkaracağını açıklamıştır. Bu tutum hangi hakka aykırıdır?', 'Sendika özgürlüğü', ['Dilekçe hakkı', 'Mülkiyet hakkı', 'Seyahat ve yerleşme hürriyeti'], 'Anayasa m.51\'e göre hiç kimse bir sendikaya üye olmaya veya üyelikten ayrılmaya zorlanamaz; üyelik nedeniyle işten çıkarma sendika özgürlüğünü ihlal eder.'),
  ('Bir kişi, aynı fiil nedeniyle beraat ettiği bir davadan sonra yeniden yargılanmak istenmektedir. Bu durum ceza hukukunun hangi ilkesine aykırıdır?', 'Aynı fiilden iki kez yargılanmama', ['Suç ve cezaların kanuniliği', 'Kanun önünde eşitlik', 'Kıyas yasağı ve lehe kanun'], 'Kesin hükümle sonuçlanan bir fiil nedeniyle kişinin yeniden yargılanmaması (ne bis in idem) adil yargılanmanın gereğidir; AİHS\'ye ek 7 No\'lu Protokolde de düzenlenmiştir.'),
  ('Bir kişi, belediyenin imar planında evinin bulunduğu alanı park alanına çevirdiğini öğrenmiş ve bu karara karşı dava açmak istiyor. Hangi yargı koluna başvurmalıdır?', 'İdari yargıya', ['Adli yargıya', 'Anayasa yargısına', 'Askerî yargıya ve disiplin kuruluna'], 'İmar planları idari işlemlerdir; bunlara karşı açılacak iptal davaları idari yargının görev alanındadır.'),
  ('Savaş ve silahlı çatışmalarda insancıl yardım ve Cenevre Sözleşmelerinin gözetiminde önemli rol oynayan ve 1863\'te kurulan örgüt hangisidir?', 'Uluslararası Kızılhaç Komitesi', ['Birleşmiş Milletler', 'Avrupa Konseyi', 'Uluslararası Af Örgütü'], 'Henry Dunant\'ın girişimiyle Cenevre\'de kurulan Uluslararası Kızılhaç Komitesi, insancıl hukukun gelişiminde öncü olmuştur.'),
  ('Birleşik Krallık\'ın anayasal düzeninin ayırt edici özelliği hangisidir?', 'Tek bir yazılı anayasa metninin bulunmaması', ['Federal bir devlet olması', 'Cumhuriyetle yönetilmesi', 'Anayasasının ABD\'den önce ve tek metin olarak yazılmış olması'], 'Birleşik Krallık\'ta anayasal kurallar Magna Carta, Bill of Rights gibi yazılı belgeler, teamüller ve yargı kararlarından oluşur; tek bir kodifiye metin yoktur.'),
  ('1787 Philadelphia Konvansiyonu\'nda hazırlanan belge aşağıdakilerden hangisidir?', 'ABD Anayasası', ['Amerikan Bağımsızlık Bildirgesi', 'İngiliz Haklar Bildirgesi', 'Fransız İnsan ve Yurttaş Hakları Bildirgesi'], 'ABD Anayasası 1787\'de Philadelphia\'da hazırlanmış, 1789\'da yürürlüğe girmiştir; Bağımsızlık Bildirgesi 1776, İngiliz Haklar Bildirgesi 1689 tarihlidir.'),
  ('Anayasa m.5\'te sayılan devletin temel amaç ve görevlerinden biri hangisidir?', 'Kişilerin ve toplumun refah, huzur ve mutluluğunu sağlamak', ['Tek bir siyasi görüşü yaymak', 'Ekonomik faaliyetlerin tamamını tekelinde tutmak', 'Vatandaşların özel hayatını sürekli izlemek ve denetlemek'], 'Anayasa m.5\'e göre devletin temel amaç ve görevleri arasında Türk milletinin bağımsızlığını ve bütünlüğünü korumak ile kişilerin ve toplumun refah, huzur ve mutluluğunu sağlamak sayılmıştır.'),
  ('Anayasa\'ya göre orman suçlarıyla ilgili hangi özel kural vardır?', 'Bu suçlar için genel af ve özel af çıkarılamaz.', ['Bu suçlar hiçbir zaman cezalandırılmaz.', 'Bu suçlar yalnız idari para cezası gerektirir.', 'Bu suçlar yalnız belediyelerce kovuşturulur ve affedilir.'], 'Anayasa m.169\'a göre ormanların yakılması, ormanı yok etme veya daraltma amaçlı suçlar için genel ve özel af çıkarılamaz.'),
  ('Anayasa m.43\'e göre kıyılar hakkında hangisi doğrudur?', 'Devletin hüküm ve tasarrufu altındadır.', ['Kıyı kenarındaki ev sahiplerinin mülkiyetindedir.', 'Yabancılara satılabilir.', 'Belediyelerin özel mülküdür ve ücretle kiralanır.'], 'Anayasa m.43\'e göre kıyılar devletin hüküm ve tasarrufu altındadır; kıyılardan yararlanmada öncelikle kamu yararı gözetilir.'),
  ('Anayasa m.38\'e göre vatandaşların suç sebebiyle yabancı bir ülkeye verilmesinin istisnası hangisidir?', 'Uluslararası Ceza Divanına taraf olmanın gerektirdiği yükümlülükler', ['Suçun her türlüsü', 'Vatandaşın kendi isteği olmaksızın her durumda', 'Yabancı ülkenin yazılı talebi'], '2004 değişikliğiyle m.38\'e eklenen hükme göre Uluslararası Ceza Divanına taraf olmanın gerektirdiği yükümlülükler hariç vatandaş suç sebebiyle yabancı ülkeye verilemez.'),
  ('Ceza muhakemesinde "şüpheli" ile "sanık" kavramları arasındaki fark nedir?', 'Soruşturma evresindeki kişi şüpheli, kovuşturma başladıktan sonraki kişi sanıktır.', ['Şüpheli mahkûm olmuş, sanık beraat etmiş kişidir.', 'Sanık yalnız hukuk davalarında, şüpheli ceza davalarında kullanılır.', 'İkisi aynı anlamdadır ve fark yoktur.'], 'CMK\'ya göre soruşturma evresinde suç şüphesi altındaki kişi şüpheli, kovuşturmanın başlamasından itibaren ise sanık adını alır.'),
  ('Ceza Muhakemesi Kanunu\'na göre kovuşturma evresi hangi işlemle başlar?', 'İddianamenin kabulü', ['Şüphelinin gözaltına alınması', 'Suç duyurusunda bulunulması', 'Polisin olay yerine gelmesi ve tutanak tutması'], 'CMK m.2\'ye göre kovuşturma, iddianamenin kabulüyle başlayıp hükmün kesinleşmesine kadar geçen evredir.'),
  ('Gözaltı ile tutuklama arasındaki temel fark nedir?', 'Tutuklama hâkim kararıyla verilen ve daha uzun süreli bir koruma tedbiridir.', ['Gözaltı yalnız hâkim kararıyla, tutuklama polis kararıyla yapılır.', 'Tutuklama yalnız hukuk davalarında uygulanır.', 'Gözaltı bir ceza türüdür ve hükümle birlikte verilir.'], 'Gözaltı kısa süreli olup Cumhuriyet savcısının emriyle yapılır; tutuklama ise sulh ceza hâkimi veya mahkeme kararıyla uygulanan bir koruma tedbiridir.'),
  ('Türk Ceza Kanunu\'nda hapis cezasının türleri hangileridir?', 'Ağırlaştırılmış müebbet, müebbet ve süreli hapis', ['Ölüm, müebbet ve sürgün', 'Kürek, sürgün ve süreli hapis', 'Müebbet, kalebentlik ve sürgün'], 'TCK m.46\'ya göre hapis cezaları ağırlaştırılmış müebbet hapis, müebbet hapis ve süreli hapis cezasıdır.'),
  ('Bir eşya üzerinde fiilî hâkimiyeti bulunan kişiye, malik olsun ya da olmasın, ne ad verilir?', 'Zilyet', ['Mirasçı', 'Kefil', 'Vasi ya da kayyım'], 'TMK m.973\'e göre bir şey üzerinde fiilî hâkimiyeti bulunan kişi o şeyin zilyedidir; kiracı da kiralananın zilyedidir.'),
  ('Türk Medeni Kanunu\'na göre yasal mirasçılıkta ilk zümreyi kimler oluşturur?', 'Altsoy', ['Kardeşler', 'Amca ve halalar', 'Büyükanne ve büyükbabalar ile onların altsoyu'], 'TMK m.495\'e göre mirasçılığın ilk derecesi miras bırakanın altsoyudur; çocuklar eşit olarak mirasçı olur.'),
  ('Anayasa m.24\'e göre din kültürü ve ahlak öğretimi ilk ve ortaöğretim kurumlarında nasıl yer alır?', 'Okutulması zorunlu dersler arasında', ['Yalnız seçmeli olarak', 'Hiç okutulmaz', 'Yalnız özel okullarda ve isteğe bağlı olarak'], 'Anayasa m.24\'e göre din ve ahlak eğitimi devletin gözetim ve denetimi altında yapılır; din kültürü ve ahlak öğretimi ilk ve ortaöğretimde zorunlu dersler arasındadır.'),
  ('Anayasa m.24\'e göre kişisel veya siyasi çıkar sağlamak amacıyla dinin veya din duygularının istismar edilmesi hakkında hangisi doğrudur?', 'Yasaktır.', ['Siyasi partilere serbesttir.', 'Seçim dönemlerinde serbesttir.', 'Yalnız valilik izniyle yapılabilir.'], 'Anayasa m.24\'e göre devletin temel düzenini kısmen de olsa din kurallarına dayandırma veya çıkar sağlama amacıyla din istismar edilemez ve kötüye kullanılamaz.'),
  ('3 Mart 1924\'te kabul edilen Tevhid-i Tedrisat Kanunu\'nun laik hukuk düzeni açısından önemi nedir?', 'Eğitimi tek çatı altında toplayıp devlet denetimine almıştır.', ['Okulları tamamen kapatmıştır.', 'Eğitimi yalnız dinî kurumlara bırakmıştır.', 'Yükseköğretimi yasaklamıştır.'], 'Tevhid-i Tedrisat ile bütün eğitim kurumları Maarif Vekâletine bağlanmış, eğitimde birlik ve laiklik sağlanmıştır.'),
  ('Dernek ile vakıf arasındaki temel fark nedir?', 'Dernek kişi topluluğu, vakıf ise belli bir amaca özgülenmiş mal topluluğudur.', ['Dernek mal topluluğu, vakıf kişi topluluğudur.', 'Dernekler kâr amaçlı şirketlerdir, vakıflar devlet kurumudur.', 'İkisi de yalnız siyasi faaliyet için kurulabilir.'], 'TMK\'ya göre dernek en az yedi kişinin bir araya gelmesiyle kurulan kişi topluluğu, vakıf ise mal varlığının belirli bir amaca özgülenmesiyle oluşan tüzel kişiliktir.'),
  ('Bir belediyenin aldığı bir kararın kanuna aykırı olduğunu düşünen İçişleri Bakanlığı, kararı doğrudan değiştiremiyor ancak kanunda öngörülen denetim yetkisini kullanabiliyor. Bu durum hangi ilişkiyi gösterir?', 'İdari vesayet', ['Hiyerarşi', 'Kuvvetler birliği', 'Yargı denetimi'], 'Yerel yönetimler ayrı tüzel kişiliğe sahip olduğundan merkezin onlar üzerindeki denetimi hiyerarşi değil, kanunla sınırlı vesayettir.'),
  ('Türkiye\'de milletvekili genel seçimlerinde sandalyelerin dağıtımında hangi yöntem kullanılmaktadır?', 'D\'Hondt yöntemi', ['Tek turlu çoğunluk', 'Saint-Laguë yöntemi', 'Tercihli oy ve tek devredilebilir oy'], '1983\'ten bu yana milletvekili seçimlerinde baraj uygulamalı D\'Hondt sistemi kullanılmaktadır.'),
  ('Anayasa m.94\'e göre bir yasama dönemi içinde TBMM Başkanlık Divanı için kaç seçim yapılır?', 'İki', ['Bir', 'Beş', 'Her yasama yılı için ayrı'], 'Anayasa m.94\'e göre bir yasama döneminde iki başkanlık divanı seçimi yapılır; ilk seçilenlerin görev süresi iki yıl, ikinci devre için seçilenlerinki üç yıldır.'),
  ('TBMM\'ye sunulan kanun teklifleri Genel Kurulda görüşülmeden önce kural olarak nerede incelenir?', 'İhtisas komisyonlarında', ['Yargıtay\'da', 'Belediye meclislerinde', 'Anayasa Mahkemesinde ve Danıştay\'da'], 'İçtüzüğe göre kanun teklifleri önce ilgili ihtisas komisyonunda görüşülür; komisyon raporuyla Genel Kurul gündemine gelir.'),
  ('2017 Anayasa değişikliğiyle hangi düzenleyici işlem türü Anayasa\'dan çıkarılmıştır?', 'Kanun hükmünde kararname', ['Yönetmelik', 'Kanun', 'Genelge ve tebliğler'], '2017 değişikliğiyle kanun hükmünde kararnameler ve tüzükler kaldırılmış, yerine Cumhurbaşkanlığı kararnamesi getirilmiştir.'),
  ('Yargıtay Cumhuriyet Başsavcısı nasıl belirlenir?', 'Cumhurbaşkanınca, Yargıtay Genel Kurulunun gösterdiği beş aday arasından seçilir.', ['TBMM\'de gizli oyla seçilir.', 'Halk oylamasıyla belirlenir.', 'Adalet Bakanınca süresiz olarak atanır.'], 'Anayasa m.154\'e göre Yargıtay Cumhuriyet Başsavcısı ve vekili, Yargıtay Genel Kurulunun kendi üyeleri arasından gösterdiği beşer aday içinden Cumhurbaşkanınca dört yıl için seçilir.'),
  ('Kanuna göre Anayasa Mahkemesine bireysel başvuru, başvuru yollarının tüketildiği veya ihlalin öğrenildiği tarihten itibaren kural olarak kaç gün içinde yapılmalıdır?', '30', ['60', '15', '90'], '6216 sayılı Kanun m.47\'ye göre bireysel başvuru, başvuru yollarının tüketildiği tarihten, yoksa ihlalin öğrenildiği tarihten itibaren otuz gün içinde yapılır.'),
  ('İdari Yargılama Usulü Kanunu\'na göre Danıştay ve idare mahkemelerinde dava açma süresi, özel kanunlarda ayrı süre gösterilmeyen hâllerde kaç gündür?', '60', ['30', '15', '120'], '2577 sayılı Kanun m.7\'ye göre dava açma süresi Danıştay ve idare mahkemelerinde altmış, vergi mahkemelerinde otuz gündür.'),
  ('Anayasa m.64\'e göre devlet sanat faaliyetlerini ve sanatçıyı korur. Bu hüküm hangi tür bir devlet yükümlülüğünü gösterir?', 'Olumlu (pozitif) yükümlülük', ['Müdahale etmeme yükümlülüğü', 'Cezalandırma yükümlülüğü', 'Vergi toplama yükümlülüğü'], 'Sanat eserlerinin ve sanatçının korunması, değerlendirilmesi ve desteklenmesi için tedbir almak devletin aktif bir edimde bulunmasını gerektirir.'),
  ('Kamu kaynaklarının tanıdık veya akraba kişilere haksız biçimde aktarılması demokratik yönetim açısından neden zararlıdır?', 'Eşitlik ve liyakat ilkelerini zedeler.', ['Seçimlerin daha sık yapılmasını sağlar.', 'Yargının bağımsızlığını güçlendirir.', 'Vatandaşların vergi yükünü kaldırır ve hizmetleri artırır.'], 'Kayırmacılık, kamu hizmetlerine ve görevlere erişimde eşitliği bozar; yönetime olan güveni azaltır.'),
  ('Bir vatandaş, valiliğin verdiği bir kararı kendi hakkını ihlal ettiği gerekçesiyle mahkemeye taşıyabilmektedir. Bu durum hukuk devletinin hangi özelliğini gösterir?', 'İdarenin yargısal denetime tabi olması', ['Kuvvetler birliği', 'Yasama dokunulmazlığı', 'Yürütmenin yargıdan üstün olması ve idari ayrıcalık'], 'Hukuk devletinde idarenin eylem ve işlemlerine karşı yargı yolu açıktır; birey devlete karşı da hakkını arayabilir.'),
  ('Seçimlerin dürüstlüğünü sağlamak için siyasi parti temsilcilerinin sandık başında bulunabilmesinin amacı nedir?', 'Seçim sürecinin denetlenebilmesi', ['Seçmenlerin oylarının açıkça görülmesi', 'Parti temsilcilerinin oy kullanmasının zorunlu olması', 'Seçimin ertelenebilmesi ve sonuçların gizli tutulması'], 'Parti temsilcilerinin gözetimi, oylamanın ve sayımın usulüne uygun yapıldığının denetlenmesini sağlar.'),
  ('Parlamenter sistemde devlet başkanının "sorumsuz" olması neden kabul edilir?', 'İşlemlerinin çoğunu başbakan ve ilgili bakanla birlikte imzalaması ve sorumluluğun hükümete ait olması', ['Devlet başkanının hiçbir işlem yapmaması', 'Devlet başkanının mahkemelerin üstünde olması', 'Devlet başkanının halk tarafından ömür boyu seçilmesi'], 'Karşı imza kuralı gereği devlet başkanının işlemleri başbakan ve ilgili bakanca da imzalanır; siyasi sorumluluk onlara aittir.'),
  ('Bir Cumhurbaşkanlığı kararnamesi ile bir kanun arasında aynı konuda farklı hükümler bulunduğunda hangisi uygulanır?', 'Kanun', ['Kararname', 'Hangisi daha yeniyse o', 'Bakanlığın tercih ettiği düzenleme'], 'Anayasa m.104\'e göre Cumhurbaşkanlığı kararnamesi ile kanunlarda farklı hükümler bulunması hâlinde kanun hükümleri uygulanır.'),
  ('Anayasa m.16\'ya göre yabancılar için temel hak ve hürriyetler nasıl sınırlanabilir?', 'Milletlerarası hukuka uygun olarak kanunla', ['Valilik genelgesiyle', 'Yalnız belediye kararıyla', 'Hiçbir şekilde sınırlanamaz ve vatandaşlardan geniş tutulur'], 'Anayasa m.16\'ya göre temel hak ve hürriyetler yabancılar için milletlerarası hukuka uygun olarak kanunla sınırlanabilir.'),
  ('Bir yurttaş, yaşadığı ildeki valiliğin bir toplantıyı gerekçesiz yasakladığını düşünüyor ve bu kararı yargıya taşımak istiyor. Bu kişinin başvuracağı yargı yolu ve dava türü hangisidir?', 'İdari yargıda iptal davası', ['Adli yargıda ceza davası', 'Anayasa Mahkemesinde iptal davası', 'Yargıtay\'da temyiz incelemesi ve duruşma'], 'Valilik kararı idari işlemdir; hukuka aykırılığı iddiasıyla idare mahkemesinde iptal davası açılır.'),
  ('Bir kanunun "torba kanun" olarak nitelendirilmesi ne anlama gelir?', 'Birbirinden farklı konulardaki birçok kanunda değişikliği tek metinde toplaması', ['Yalnız bir maddeden oluşması', 'Yalnız uluslararası antlaşmaları onaylaması', 'Halk oylamasıyla kabul edilmiş olması ve değiştirilememesi'], 'Torba kanunlar farklı alanlara ilişkin çok sayıda değişikliği aynı metinde düzenler; yasama sürecinin şeffaflığı açısından eleştirilir.'),
];
